window.NEURO = {"questions": [{"id": "Q001", "ref": "1.1-3", "deck": "1.1", "topic": "Organization", "stem": "Which structure is part of the central nervous system?", "options": [{"text": "Dorsal root ganglion", "why": "This contains peripheral sensory cell bodies."}, {"text": "Sympathetic trunk", "why": "Its ganglia and axons belong to the PNS."}, {"text": "Spinal cord", "why": "The CNS comprises the brain and spinal cord."}, {"text": "Median nerve", "why": "This is a peripheral nerve."}, {"text": "Celiac ganglion", "why": "This is a peripheral autonomic ganglion."}], "answer": 2}, {"id": "Q002", "ref": "1.1-3", "deck": "1.1", "topic": "Organization", "stem": "A histologic section shows a cluster of neuronal cell bodies outside the brain and spinal cord. What is the most appropriate general term?", "options": [{"text": "Ganglion", "why": "Ganglia are PNS collections of neuronal cell bodies."}, {"text": "Tract", "why": "A tract is a CNS axon bundle."}, {"text": "Nerve", "why": "A nerve is a PNS axon bundle."}, {"text": "White matter", "why": "White matter is CNS tissue enriched in myelinated axons."}, {"text": "Nucleus", "why": "A nucleus is a CNS cell-body collection."}], "answer": 0}, {"id": "Q003", "ref": "1.1-4", "deck": "1.1", "topic": "Organization", "stem": "Stretch of a carotid arterial wall activates neurons that convey information toward the brainstem. How is this pathway classified?", "options": [{"text": "Visceral afferent", "why": "It carries sensory information from a blood vessel toward the CNS."}, {"text": "Somatic afferent", "why": "This refers to sensation from structures such as skin and skeletal muscle."}, {"text": "Visceral efferent", "why": "This carries autonomic commands away from the CNS."}, {"text": "Postganglionic sympathetic", "why": "This is an efferent autonomic classification, not the sensory route described."}, {"text": "Somatic efferent", "why": "This supplies skeletal muscle from the CNS."}], "answer": 0}, {"id": "Q004", "ref": "1.1-4", "deck": "1.1", "topic": "Organization", "stem": "A motor neuron directly activates a skeletal muscle during an involuntary tendon reflex. Which division contains this efferent neuron?", "options": [{"text": "Somatic motor", "why": "Its skeletal-muscle target defines it as somatic even though the reflex is involuntary."}, {"text": "Visceral sensory", "why": "Sensory neurons carry input toward the CNS."}, {"text": "Enteric sensory", "why": "These participate in intrinsic gut circuits."}, {"text": "Sympathetic motor", "why": "Sympathetic neurons do not directly activate skeletal muscle fibers at their neuromuscular junctions."}, {"text": "Parasympathetic motor", "why": "Parasympathetic targets are visceral effectors."}], "answer": 0}, {"id": "Q005", "ref": "1.1-5", "deck": "1.1", "topic": "Roots and rami", "stem": "A small lesion selectively destroys the left dorsal root of a spinal nerve without injuring its ventral root. Which deficit is expected in its distribution?", "options": [{"text": "Loss of all contralateral body sensation", "why": "A single root does not carry all contralateral sensation."}, {"text": "Direct paralysis of both cerebral hemispheres", "why": "The root is a peripheral segmental structure."}, {"text": "Isolated loss of voluntary motor output", "why": "Motor axons exit through the ventral root."}, {"text": "Complete loss of ipsilateral facial movement", "why": "Facial motor output travels through CN VII, not a spinal dorsal root."}, {"text": "Loss of sensory input", "why": "The dorsal root carries afferents into the cord."}], "answer": 4}, {"id": "Q006", "ref": "1.1-5", "deck": "1.1", "topic": "Roots and rami", "stem": "Where are the cell bodies of primary sensory neurons carrying pain from the foot to the spinal cord?", "options": [{"text": "Posterior column", "why": "This is an ascending white-matter pathway, not the location of primary somata."}, {"text": "Lateral horn", "why": "This contains autonomic preganglionic neurons at appropriate levels."}, {"text": "Sympathetic chain ganglion", "why": "This contains postganglionic sympathetic somata."}, {"text": "Anterior horn", "why": "This contains somatic lower motor neuron cell bodies."}, {"text": "Dorsal root ganglion", "why": "Spinal primary sensory somata lie in DRG."}], "answer": 4}, {"id": "Q007", "ref": "1.1-5", "deck": "1.1", "topic": "Roots and rami", "stem": "Following a penetrating injury, a patient loses sensation from a patch of back skin and develops weakness of nearby intrinsic back muscles. Which structure could account for both findings?", "options": [{"text": "Anterior white commissure", "why": "This CNS crossing primarily involves segmental pain-temperature pathways."}, {"text": "Gray ramus alone", "why": "This carries sympathetic efferents, not the somatic motor and sensory combination."}, {"text": "Ventral root alone", "why": "This carries efferents and would not directly eliminate cutaneous afferents."}, {"text": "Dorsal ramus", "why": "Dorsal rami are mixed and serve intrinsic back muscles and overlying skin."}, {"text": "Dorsal root alone", "why": "This carries sensory fibers rather than motor output."}], "answer": 3}, {"id": "Q008", "ref": "1.1-5", "deck": "1.1", "topic": "Roots and rami", "stem": "Which statement about a spinal nerve immediately after the anterior and posterior roots unite is correct?", "options": [{"text": "It contains sensory and motor axons", "why": "The united spinal nerve is mixed."}, {"text": "It contains only somatic efferents", "why": "Both afferents and efferents are present."}, {"text": "It contains only afferents", "why": "That describes the dorsal root more closely."}, {"text": "Its dorsal ramus is exclusively sensory", "why": "Both major rami are mixed."}, {"text": "It is a CNS tract", "why": "A spinal nerve is PNS."}], "answer": 0}, {"id": "Q009", "ref": "1.1-6", "deck": "1.1", "topic": "Autonomic pathways", "stem": "A neuron in the spinal cord sends an axon to a peripheral ganglion; a second neuron innervates vascular smooth muscle. This arrangement is characteristic of which pathway?", "options": [{"text": "Autonomic motor", "why": "The usual autonomic chain contains preganglionic and postganglionic neurons."}, {"text": "Primary somatic sensory pathway", "why": "Primary sensory neurons do not use this efferent two-neuron organization."}, {"text": "Optic pathway", "why": "This conveys visual sensory information."}, {"text": "Final somatic motor pathway", "why": "A single lower motor neuron runs from CNS to skeletal muscle."}, {"text": "Corticospinal tract alone", "why": "This is a CNS descending tract, not the full ganglion-to-visceral-effector chain."}], "answer": 0}, {"id": "Q010", "ref": "1.1-7", "deck": "1.1", "topic": "Autonomic pathways", "stem": "A drug blocks nicotinic neuronal receptors in autonomic ganglia. Which transmission is directly blocked?", "options": [{"text": "Somatic neuromuscular input", "why": "That uses nicotinic muscle receptors rather than Nn."}, {"text": "Sensory transduction in a skin receptor", "why": "This is not the autonomic ganglionic synapse targeted."}, {"text": "Preganglionic-to-postganglionic transmission", "why": "Both autonomic divisions use acetylcholine at Nn receptors in ganglia."}, {"text": "Parasympathetic postganglionic input to detrusor", "why": "That uses muscarinic receptors."}, {"text": "Most sympathetic postganglionic input to vessels", "why": "That uses adrenergic receptors."}], "answer": 2}, {"id": "Q011", "ref": "1.1-7", "deck": "1.1", "topic": "Autonomic pathways", "stem": "Which organ receives direct preganglionic sympathetic input onto modified postganglionic cells that secrete into blood?", "options": [{"text": "Distal colon", "why": "Its parasympathetic fibers relay in intramural ganglia."}, {"text": "Adrenal cortex", "why": "Its steroid secretion is not this ganglionic catecholamine pathway."}, {"text": "Adrenal medulla", "why": "Chromaffin cells are modified sympathetic ganglion cells."}, {"text": "Parotid gland", "why": "Its parasympathetic relay is the otic ganglion."}, {"text": "Skeletal muscle endplate", "why": "This receives a somatic motor axon."}], "answer": 2}, {"id": "Q012", "ref": "1.1-8", "deck": "1.1", "topic": "Sympathetic pathways", "stem": "Preganglionic sympathetic neuron cell bodies supplying the body are concentrated in which spinal cord region?", "options": [{"text": "Dorsal root ganglia at all levels", "why": "These contain primary sensory somata."}, {"text": "Cerebellar cortex", "why": "This is involved in motor coordination, not sympathetic preganglionic origin."}, {"text": "Intermediolateral column at T1-L2", "why": "This is the thoracolumbar sympathetic outflow."}, {"text": "Anterior horn at C1-C4", "why": "This contains somatic motor neurons rather than the main sympathetic outflow."}, {"text": "Posterior horn at S2-S4", "why": "This is not the thoracolumbar preganglionic sympathetic column."}], "answer": 2}, {"id": "Q013", "ref": "1.1-8", "deck": "1.1", "topic": "Sympathetic pathways", "stem": "Which sequence correctly carries a sympathetic preganglionic axon from spinal cord into the sympathetic chain?", "options": [{"text": "Ventral root → gray ramus → dorsal root", "why": "Gray rami are not the normal preganglionic entry route."}, {"text": "Dorsal root ganglion → ventral root → chain", "why": "DRG somata are sensory, not sympathetic preganglionic neurons."}, {"text": "Ventral root → spinal nerve → white ramus", "why": "This is the standard entry route from T1-L2."}, {"text": "Dorsal root → spinal nerve → gray ramus", "why": "Dorsal roots are afferent and gray rami carry postganglionic output."}, {"text": "Posterior column → cranial nerve → white ramus", "why": "The posterior column is a CNS ascending sensory pathway."}], "answer": 2}, {"id": "Q014", "ref": "1.1-8", "deck": "1.1", "topic": "Sympathetic pathways", "stem": "A sympathetic preganglionic fiber leaves the T2 cord and ultimately synapses in the superior cervical ganglion. What occurs between entry into the trunk and synapse?", "options": [{"text": "It synapses first in a dorsal root ganglion", "why": "DRG are sensory ganglia without the autonomic relay."}, {"text": "It passes through a cervical white ramus", "why": "Cervical levels have no white rami."}, {"text": "It becomes a pelvic splanchnic fiber", "why": "Pelvic splanchnics are sacral parasympathetic nerves."}, {"text": "It ascends within the sympathetic trunk", "why": "Thoracic outflow reaches cervical ganglia by ascending in the chain."}, {"text": "It crosses the cerebral aqueduct", "why": "The aqueduct is a CSF conduit."}], "answer": 3}, {"id": "Q015", "ref": "1.1-9", "deck": "1.1", "topic": "Sympathetic pathways", "stem": "Which ramus is expected on a typical C6 spinal nerve?", "options": [{"text": "A pelvic splanchnic ramus", "why": "Pelvic splanchnics arise from S2-S4."}, {"text": "Gray ramus without a white ramus", "why": "Gray rami occur at all levels; white rami are limited to T1-L2."}, {"text": "White ramus without a gray ramus", "why": "C6 does not have white rami."}, {"text": "Neither white nor gray ramus", "why": "A gray ramus supplies postganglionic sympathetic fibers."}, {"text": "Both white and gray rami", "why": "White rami are absent at cervical levels."}], "answer": 1}, {"id": "Q016", "ref": "1.1-9", "deck": "1.1", "topic": "Sympathetic pathways", "stem": "A nerve sample contains unmyelinated postganglionic sympathetic axons returning from the sympathetic chain to a spinal nerve. Which structure was sampled?", "options": [{"text": "White ramus communicans", "why": "White rami carry predominantly myelinated preganglionic sympathetic efferents into the chain."}, {"text": "Greater splanchnic nerve", "why": "This primarily carries preganglionic sympathetic fibers toward prevertebral ganglia."}, {"text": "Gray ramus communicans", "why": "Gray rami carry postganglionic sympathetic axons toward spinal nerves."}, {"text": "Dorsal root", "why": "This carries sensory input toward the cord."}, {"text": "Pelvic splanchnic nerve", "why": "This carries preganglionic parasympathetic fibers."}], "answer": 2}, {"id": "Q017", "ref": "1.1-10", "deck": "1.1", "topic": "Splanchnic and pelvic pathways", "stem": "Which nerve primarily carries preganglionic parasympathetic fibers?", "options": [{"text": "Sacral splanchnic nerve", "why": "These primarily carry postganglionic sympathetic fibers."}, {"text": "Pelvic splanchnic nerve", "why": "Pelvic splanchnics arise from S2-S4."}, {"text": "Greater thoracic splanchnic nerve", "why": "This primarily carries preganglionic sympathetic fibers."}, {"text": "Lumbar splanchnic nerve", "why": "This primarily carries preganglionic sympathetic fibers."}, {"text": "Cardiopulmonary splanchnic nerve", "why": "These carry postganglionic sympathetic fibers."}], "answer": 1}, {"id": "Q018", "ref": "1.1-10", "deck": "1.1", "topic": "Splanchnic and pelvic pathways", "stem": "A surgeon identifies a nerve leaving a sacral sympathetic ganglion and entering the inferior hypogastric plexus. What fibers does it primarily contain?", "options": [{"text": "Postganglionic sympathetic", "why": "This describes a sacral splanchnic nerve."}, {"text": "Somatic motor only", "why": "This is an autonomic route rather than a skeletal-muscle nerve."}, {"text": "Optic sensory axons", "why": "These do not enter pelvic plexuses."}, {"text": "Preganglionic sympathetic from a sacral lateral horn", "why": "Sympathetic preganglionic origin is thoracolumbar, not sacral."}, {"text": "Preganglionic parasympathetic", "why": "These arrive through pelvic splanchnics from S2-S4."}], "answer": 0}, {"id": "Q019", "ref": "1.1-11", "deck": "1.1", "topic": "Splanchnic and pelvic pathways", "stem": "A sympathetic fiber supplying the stomach passes through the sympathetic chain without synapsing. Where does it most likely synapse next?", "options": [{"text": "Submandibular ganglion", "why": "This parasympathetic ganglion serves salivary glands."}, {"text": "Dorsal root ganglion", "why": "There is no autonomic efferent relay there."}, {"text": "Inferior mesenteric ganglion", "why": "This primarily serves hindgut rather than stomach."}, {"text": "Ciliary ganglion", "why": "This parasympathetic ganglion serves ocular smooth muscle."}, {"text": "Celiac ganglion", "why": "This prevertebral ganglion primarily serves foregut."}], "answer": 4}, {"id": "Q020", "ref": "1.1-11", "deck": "1.1", "topic": "Splanchnic and pelvic pathways", "stem": "Postganglionic sympathetic axons leaving a superior mesenteric ganglion most commonly reach midgut organs by following which structures?", "options": [{"text": "Optic tracts", "why": "These are visual CNS pathways."}, {"text": "Dorsal roots into the spinal cord", "why": "This would lead toward the CNS rather than the organs."}, {"text": "Gray rami to cervical nerves", "why": "This is a body-wall route at the wrong region."}, {"text": "Arterial branches", "why": "Periarterial plexuses distribute sympathetic fibers to abdominal viscera."}, {"text": "Cerebral ventricles", "why": "These are CSF cavities."}], "answer": 3}, {"id": "Q021", "ref": "1.1-12", "deck": "1.1", "topic": "Parasympathetic pathways", "stem": "Which cranial nerve carries preganglionic parasympathetic fibers destined for the ciliary ganglion?", "options": [{"text": "CN II", "why": "This carries visual afferents and is a CNS extension."}, {"text": "CN XII", "why": "This supplies tongue skeletal muscle."}, {"text": "CN VI", "why": "This innervates lateral rectus and lacks this parasympathetic outflow."}, {"text": "CN V", "why": "Trigeminal branches distribute some postganglionic fibers but do not originate this preganglionic route."}, {"text": "CN III", "why": "Oculomotor parasympathetic fibers supply pupil constriction and accommodation through this ganglion."}], "answer": 4}, {"id": "Q022", "ref": "1.1-12", "deck": "1.1", "topic": "Parasympathetic pathways", "stem": "After injury to preganglionic fibers traveling with CN IX, which gland's parasympathetic secretion is most directly reduced?", "options": [{"text": "Submandibular", "why": "This is supplied by CN VII through submandibular ganglion."}, {"text": "Adrenal medulla", "why": "This receives sympathetic preganglionic input."}, {"text": "Lacrimal", "why": "This is supplied by CN VII through pterygopalatine ganglion."}, {"text": "Parotid", "why": "CN IX relays through the otic ganglion to the parotid."}, {"text": "Sublingual", "why": "This also receives CN VII-related input."}], "answer": 3}, {"id": "Q023", "ref": "1.1-12", "deck": "1.1", "topic": "Parasympathetic pathways", "stem": "Which pattern best describes the usual parasympathetic motor chain?", "options": [{"text": "Short preganglionic and long postganglionic fibers", "why": "This is more typical of sympathetic chain organization."}, {"text": "No peripheral synapse", "why": "Most parasympathetic output requires a ganglionic relay."}, {"text": "Sensory cell body in a ventral horn", "why": "Primary sensory somata are not in ventral horn."}, {"text": "Long preganglionic and short postganglionic fibers", "why": "Ganglia usually lie near or within the target."}, {"text": "One CNS neuron directly ending on skeletal muscle", "why": "This is the final somatic efferent route."}], "answer": 3}, {"id": "Q024", "ref": "1.1-13", "deck": "1.1", "topic": "Parasympathetic pathways", "stem": "A lesion interrupts the vagal trunks below the diaphragm. Which region most directly loses its usual parasympathetic supply?", "options": [{"text": "Jejunum", "why": "Midgut receives vagal parasympathetic supply."}, {"text": "Urinary bladder", "why": "This receives pelvic parasympathetic fibers."}, {"text": "External anal sphincter", "why": "This skeletal muscle receives somatic pudendal input."}, {"text": "Descending colon", "why": "Hindgut receives pelvic splanchnic input."}, {"text": "Rectum", "why": "Its parasympathetic supply is sacral."}], "answer": 0}, {"id": "Q025", "ref": "1.1-13", "deck": "1.1", "topic": "Parasympathetic pathways", "stem": "During pelvic surgery, bilateral pelvic splanchnic nerves are injured. Which function is most directly impaired?", "options": [{"text": "Vagal stimulation of the stomach", "why": "Vagal input does not arise from pelvic splanchnics."}, {"text": "Sympathetic activation of eccrine glands in the hand", "why": "This travels through sympathetic chain and spinal nerves."}, {"text": "Pupillary constriction through ciliary ganglion", "why": "This is CN III parasympathetic output."}, {"text": "Voluntary elbow flexion", "why": "This is somatic upper-limb motor function."}, {"text": "Parasympathetic stimulation of hindgut motility", "why": "S2-S4 pelvic splanchnics serve hindgut and pelvic viscera."}], "answer": 4}, {"id": "Q026", "ref": "1.1-14", "deck": "1.1", "topic": "Splanchnic and pelvic pathways", "stem": "Which structure normally contains both sympathetic and parasympathetic efferents to pelvic organs?", "options": [{"text": "Pelvic splanchnic nerve alone", "why": "Its efferents are parasympathetic."}, {"text": "Gray ramus communicans", "why": "Its efferents are sympathetic postganglionic."}, {"text": "Ciliary ganglion", "why": "This is a cranial parasympathetic ganglion."}, {"text": "Inferior hypogastric plexus", "why": "It receives hypogastric/sacral sympathetic and pelvic parasympathetic inputs."}, {"text": "White ramus communicans", "why": "Its efferents are sympathetic preganglionic."}], "answer": 3}, {"id": "Q027", "ref": "1.1-14", "deck": "1.1", "topic": "Splanchnic and pelvic pathways", "stem": "The superior hypogastric plexus descends into the pelvis primarily through which paired structures?", "options": [{"text": "Pudendal nerves", "why": "These are somatic S2-S4 nerves rather than the superior-plexus continuation."}, {"text": "Greater petrosal nerves", "why": "These are cranial parasympathetic routes toward pterygopalatine ganglia."}, {"text": "Vagal trunks", "why": "These carry cranial parasympathetic supply to foregut/midgut."}, {"text": "Hypogastric nerves", "why": "Right and left hypogastric nerves connect superior and inferior hypogastric plexuses."}, {"text": "Phrenic nerves", "why": "These supply the diaphragm and sensory territories."}], "answer": 3}, {"id": "Q028", "ref": "1.1-15", "deck": "1.1", "topic": "Enteric system", "stem": "A biopsy identifies neurons between the circular and longitudinal layers of muscularis externa. Which function is most closely associated with this plexus?", "options": [{"text": "Production of CSF", "why": "This is mainly a choroid plexus function."}, {"text": "Primary regulation of mucosal secretion from the submucosa", "why": "This is more characteristic of Meissner plexus."}, {"text": "Secretion of adrenal catecholamines", "why": "This occurs in adrenal medulla."}, {"text": "Coordination of gut motility", "why": "The myenteric/Auerbach plexus lies between these muscle layers."}, {"text": "Voluntary external sphincter contraction", "why": "This uses somatic motor neurons."}], "answer": 3}, {"id": "Q029", "ref": "1.1-15", "deck": "1.1", "topic": "Enteric system", "stem": "A full-term newborn has not passed meconium 48 hours after delivery. His abdomen is distended, and he develops bilious vomiting. Imaging shows a narrow distal colonic segment with dilation of the bowel proximal to it. Rectal suction biopsy shows absence of ganglion cells in the sampled enteric plexuses. The clinical team explains that the distal segment cannot coordinate normal relaxation even though the bowel is not physically blocked by a foreign body. Which mechanism most directly explains the functional obstruction?", "options": [{"text": "Rupture of a middle meningeal artery", "why": "This causes intracranial bleeding, not aganglionosis."}, {"text": "Failure of enteric-mediated distal bowel relaxation", "why": "Hirschsprung disease results from distal enteric aganglionosis."}, {"text": "Aqueduct obstruction", "why": "This causes ventricular dilation, not a narrow distal bowel segment."}, {"text": "Excess vagal innervation of the rectum", "why": "The rectum normally receives sacral parasympathetic input, and excess vagal supply is not the mechanism."}, {"text": "Loss of oligodendrocytes in the colon", "why": "Oligodendrocytes are CNS glia."}], "answer": 1}, {"id": "Q030", "ref": "1.1-16", "deck": "1.1", "topic": "Enteric system", "stem": "Which combination normally promotes digestion in the distal colon?", "options": [{"text": "Gray ramus input with direct skeletal muscle activation", "why": "Gray rami carry autonomic fibers, not somatic endplate axons."}, {"text": "CN III input with increased peristalsis", "why": "CN III parasympathetic output serves the eye."}, {"text": "Vagal input with reduced motility", "why": "Vagus mainly serves foregut/midgut and parasympathetic activity generally increases motility."}, {"text": "Lumbar sympathetic input with increased secretion", "why": "Sympathetic activity generally suppresses secretion and motility."}, {"text": "Pelvic parasympathetic input with increased motility/secretion", "why": "Hindgut receives S2-S4 parasympathetic input."}], "answer": 4}, {"id": "Q031", "ref": "1.1-17", "deck": "1.1", "topic": "Sensory pathways", "stem": "A patient with myocardial ischemia experiences pain in the left medial arm. Which mechanism best explains this referred pain?", "options": [{"text": "Pain generation by the sympathetic ganglion's skeletal muscle", "why": "Ganglia do not contain skeletal muscle effectors."}, {"text": "Crossing of all visceral fibers in the optic chiasm", "why": "The chiasm is a visual structure."}, {"text": "Convergence of visceral and somatic afferents in spinal circuits", "why": "Shared processing can cause visceral activity to be perceived in a somatic territory."}, {"text": "Cardiac postganglionic fibers becoming arm motor axons", "why": "Autonomic efferents do not transform into somatic motor neurons."}, {"text": "Direct spread of blood into the arm's CSF", "why": "The arm has no CSF compartment."}], "answer": 2}, {"id": "Q032", "ref": "1.1-17", "deck": "1.1", "topic": "Sensory pathways", "stem": "Which statement best distinguishes a visceral afferent from a sympathetic efferent traveling in the same splanchnic nerve?", "options": [{"text": "The afferent is defined by being unmyelinated", "why": "Myelination alone does not define direction or function."}, {"text": "The afferent originates from a lateral horn motor soma", "why": "Its soma lies in a sensory ganglion."}, {"text": "The afferent conducts information toward the CNS", "why": "Shared routes do not change sensory versus motor direction."}, {"text": "The afferent must synapse in a sympathetic ganglion", "why": "Sensory afferents generally pass through autonomic ganglia."}, {"text": "The afferent always innervates skeletal muscle", "why": "Visceral afferents arise from viscera and vessels."}], "answer": 2}, {"id": "Q033", "ref": "1.1-18", "deck": "1.1", "topic": "Orientation", "stem": "In a forebrain diagram, an arrow points dorsally. Toward which surface does it point?", "options": [{"text": "Inferior surface", "why": "This is ventral in forebrain."}, {"text": "Always toward the patient's right", "why": "Dorsal does not specify left/right."}, {"text": "Superior surface", "why": "Dorsal corresponds to superior in the bent forebrain neuraxis."}, {"text": "Anterior surface", "why": "This is rostral in forebrain."}, {"text": "Posterior surface", "why": "This is caudal in forebrain."}], "answer": 2}, {"id": "Q034", "ref": "1.1-18", "deck": "1.1", "topic": "Orientation", "stem": "Which imaging plane divides the brain into anterior and posterior portions?", "options": [{"text": "Axial", "why": "Axial/horizontal planes separate superior and inferior."}, {"text": "Oblique along the neuraxis only", "why": "An oblique plane is not the standard anterior-posterior division."}, {"text": "Midsagittal", "why": "This specifically divides left and right at midline."}, {"text": "Coronal", "why": "Coronal/frontal planes separate anterior from posterior."}, {"text": "Sagittal", "why": "Sagittal planes separate left and right."}], "answer": 3}, {"id": "Q035", "ref": "1.1-19", "deck": "1.1", "topic": "CNS regions", "stem": "A lesion affects the pons. Which major brain division contains this structure?", "options": [{"text": "Cerebellar cortex", "why": "The pons connects with cerebellum but is not cerebellar cortex."}, {"text": "Peripheral nervous system", "why": "Pons is CNS."}, {"text": "Cerebral cortex", "why": "Pons is not part of cortical gray matter."}, {"text": "Brainstem", "why": "The brainstem consists of midbrain, pons, and medulla."}, {"text": "Telencephalon", "why": "This gives rise to cerebral hemispheres rather than pons."}], "answer": 3}, {"id": "Q036", "ref": "1.1-19", "deck": "1.1", "topic": "CNS regions", "stem": "Which embryonic region gives rise to the pons and cerebellum?", "options": [{"text": "Metencephalon", "why": "This hindbrain subdivision forms pons and cerebellum."}, {"text": "Telencephalon", "why": "This forms cerebral hemispheres."}, {"text": "Diencephalon", "why": "This forms structures including thalamus and hypothalamus."}, {"text": "Mesencephalon", "why": "This forms midbrain."}, {"text": "Myelencephalon", "why": "This forms medulla."}], "answer": 0}, {"id": "Q037", "ref": "1.1-20", "deck": "1.1", "topic": "Gray and white matter", "stem": "Which observation corrects the statement that all brain gray matter is superficial?", "options": [{"text": "All spinal gray matter lies outside white matter", "why": "The spinal cord has central gray and peripheral white matter."}, {"text": "White matter contains no glia", "why": "White matter contains supporting glia."}, {"text": "Myelin is concentrated only in neuronal somata", "why": "Myelin wraps axons."}, {"text": "Gray matter contains no axons", "why": "Gray matter includes axonal processes as well as somata and synapses."}, {"text": "Deep cerebral nuclei are gray matter", "why": "Gray matter includes cortical and deep nuclear regions."}], "answer": 4}, {"id": "Q038", "ref": "1.1-20", "deck": "1.1", "topic": "Gray and white matter", "stem": "In an axial spinal cord section, what is the butterfly-shaped central region?", "options": [{"text": "Subarachnoid cistern", "why": "This surrounds neural tissue rather than forming its central horns."}, {"text": "Gray matter", "why": "Spinal gray matter forms central horns around the central canal."}, {"text": "Sympathetic trunk", "why": "This lies outside the vertebral canal."}, {"text": "Peripheral white matter", "why": "This surrounds the gray matter."}, {"text": "Dorsal root ganglion", "why": "DRG lie outside the cord."}], "answer": 1}, {"id": "Q039", "ref": "1.1-21", "deck": "1.1", "topic": "Neurons", "stem": "Action potentials in a typical neuron most often initiate in which region?", "options": [{"text": "Dendritic spine exclusively", "why": "Dendrites usually integrate synaptic input rather than serve as the usual trigger zone."}, {"text": "Myelin lipid layer", "why": "Myelin insulates rather than regenerates spikes."}, {"text": "Nucleolus", "why": "This synthesizes ribosomal components."}, {"text": "Synaptic cleft", "why": "This extracellular gap receives transmitter, not neuronal action-potential initiation."}, {"text": "Axon initial segment near the hillock", "why": "Its high sodium-channel density supports spike initiation."}], "answer": 4}, {"id": "Q040", "ref": "1.1-21", "deck": "1.1", "topic": "Neurons", "stem": "A pathologist describes a bundle of axons entirely within the spinal cord. Which term is most appropriate?", "options": [{"text": "Nerve", "why": "Nerves are PNS axon bundles."}, {"text": "Ganglion", "why": "This is a PNS cell-body collection."}, {"text": "Nucleus", "why": "This is a CNS cell-body collection."}, {"text": "Tract", "why": "CNS axon bundles are called tracts."}, {"text": "Soma", "why": "This refers to an individual neuron cell body."}], "answer": 3}, {"id": "Q041", "ref": "1.1-22", "deck": "1.1", "topic": "Glia", "stem": "Which CNS cell has a developmental origin distinct from neural-tube-derived macroglia?", "options": [{"text": "Astrocyte", "why": "Astrocytes are neuroectodermal macroglia."}, {"text": "Ependymal cell", "why": "These derive from neural-tube neuroepithelium."}, {"text": "Cortical neuron", "why": "This also derives from neural neuroectoderm rather than macrophage lineage."}, {"text": "Microglia", "why": "Microglia arise from embryonic yolk-sac macrophage lineage."}, {"text": "Oligodendrocyte", "why": "These are neuroectodermal myelinating glia."}], "answer": 3}, {"id": "Q042", "ref": "1.1-22", "deck": "1.1", "topic": "Glia", "stem": "Which cell supports neuronal somata in a peripheral sensory ganglion?", "options": [{"text": "Pyramidal neuron", "why": "This is a neuron rather than a peripheral supportive glial cell."}, {"text": "Ependymal cell", "why": "These line CSF cavities."}, {"text": "Microglial cell", "why": "These are CNS resident immune cells."}, {"text": "Oligodendrocyte", "why": "These myelinate CNS axons."}, {"text": "Satellite glial cell", "why": "Satellite glia surround PNS ganglion cell bodies."}], "answer": 4}, {"id": "Q043", "ref": "1.1-23", "deck": "1.1", "topic": "Glia", "stem": "A single glial cell produces myelin internodes on multiple axons in the brain. Which cell is it?", "options": [{"text": "Microglia", "why": "These are immune cells rather than myelin-forming cells."}, {"text": "Schwann cell", "why": "One myelinating Schwann cell forms one internode on one PNS axon."}, {"text": "Satellite cell", "why": "This supports PNS ganglion somata."}, {"text": "Oligodendrocyte", "why": "One oligodendrocyte can myelinate segments of several CNS axons."}, {"text": "Astrocyte", "why": "Astrocytes support homeostasis and barrier maintenance but do not form myelin."}], "answer": 3}, {"id": "Q044", "ref": "1.1-23", "deck": "1.1", "topic": "Glia", "stem": "A 24-year-old woman reports three days of reduced vision in her right eye and pain that worsens when she moves the eye. She recalls a prior episode of left leg numbness that resolved over several weeks. Brain MRI shows multiple lesions in CNS white matter, and the optic nerve is inflamed. The clinician explains that despite its name, the optic nerve is a CNS extension and is covered by meninges. Which myelin-producing cell is most directly implicated in this disease process?", "options": [{"text": "Microglia", "why": "These may participate in inflammation but are not the myelin-producing cells asked for."}, {"text": "Oligodendrocyte", "why": "Optic nerve is CNS and is myelinated by oligodendrocytes."}, {"text": "Satellite cell", "why": "These surround PNS ganglion somata."}, {"text": "Choroid epithelial cell", "why": "These secrete CSF."}, {"text": "Schwann cell", "why": "These form PNS myelin rather than optic-nerve myelin."}], "answer": 1}, {"id": "Q045", "ref": "1.1-23", "deck": "1.1", "topic": "Glia", "stem": "A 32-year-old man develops tingling in both feet ten days after a respiratory infection. Over the next four days, weakness spreads from his legs to his arms. Examination shows symmetric weakness and absent deep tendon reflexes without an extensor plantar response. Nerve conduction studies demonstrate slowed peripheral conduction, and a demyelinating polyradiculoneuropathy is diagnosed. He is admitted for respiratory and autonomic monitoring. Which cell normally produces the myelin affected in the common demyelinating form of this disorder?", "options": [{"text": "Ependymal cell", "why": "This lines ventricular cavities."}, {"text": "Pyramidal neuron", "why": "This is an upper motor neuron, not a peripheral myelin cell."}, {"text": "Schwann cell", "why": "The common demyelinating form of Guillain-Barré affects peripheral myelin."}, {"text": "Astrocyte", "why": "This is not a myelin-forming cell."}, {"text": "Oligodendrocyte", "why": "This is CNS myelin, as affected in MS."}], "answer": 2}, {"id": "Q046", "ref": "1.1-23", "deck": "1.1", "topic": "Glia", "stem": "Which statement most accurately explains the astrocyte's relationship to the blood-brain barrier?", "options": [{"text": "Astrocytes produce all ventricular CSF", "why": "Choroid plexus epithelium is the major source."}, {"text": "Astrocytes form the capillary lumen's endothelial lining", "why": "The lumen is lined by endothelial cells."}, {"text": "Astrocytes myelinate peripheral axons", "why": "Schwann cells do this."}, {"text": "Astrocytes are the main latent reservoir of VZV in DRG", "why": "VZV classically persists in sensory neurons."}, {"text": "Astrocytes help maintain endothelial tight-junction properties", "why": "Endothelial cells form the physical BBB seal, supported by astrocytic endfeet."}], "answer": 4}, {"id": "Q047", "ref": "1.1-23", "deck": "1.1", "topic": "Glia", "stem": "Which cell lines the cerebral ventricles and contributes to movement of CSF along their surfaces?", "options": [{"text": "Ependymal cell", "why": "Ciliated ependymal cells line ventricles and central canal."}, {"text": "Dural fibroblast", "why": "This contributes connective tissue rather than ventricular lining."}, {"text": "Schwann cell", "why": "These form peripheral myelin."}, {"text": "Osteocyte", "why": "This is a bone cell."}, {"text": "Satellite cell", "why": "These support peripheral ganglion somata."}], "answer": 0}, {"id": "Q048", "ref": "1.1-23", "deck": "1.1", "topic": "Glia", "stem": "Varicella-zoster virus reactivates in a sensory ganglion. Which cell is the classic site of latent viral persistence?", "options": [{"text": "Astrocyte endfoot", "why": "This supports CNS vessels rather than being the classic ganglionic latent reservoir."}, {"text": "Sensory neuron", "why": "VZV latency is classically neuronal; satellite glia support the ganglion."}, {"text": "Choroid epithelial cell", "why": "These form the blood-CSF barrier."}, {"text": "Ependymal cell", "why": "These line ventricles."}, {"text": "Oligodendrocyte", "why": "These are CNS myelin cells."}], "answer": 1}, {"id": "Q049", "ref": "1.1-7", "deck": "1.1", "topic": "Autonomic pathways", "stem": "A patient has impaired sweating after injury to sympathetic fibers supplying skin. What transmitter normally acts at most eccrine sweat glands?", "options": [{"text": "Norepinephrine exclusively", "why": "Most sympathetic effectors are adrenergic, but eccrine sweat glands are a key exception."}, {"text": "Dopamine at D2 receptors", "why": "This is not the usual eccrine effector signal."}, {"text": "Acetylcholine", "why": "Eccrine sympathetic postganglionic fibers are a cholinergic exception and act at muscarinic receptors."}, {"text": "Serotonin at 5-HT3 receptors", "why": "This is not the main eccrine sympathetic effector signal."}, {"text": "Glutamate at NMDA receptors", "why": "This is not the peripheral sweating transmitter."}], "answer": 2}, {"id": "Q050", "ref": "1.1-15", "deck": "1.1", "topic": "Enteric system", "stem": "Which enteric plexus is most directly associated with mucosal secretion and local blood flow?", "options": [{"text": "Submucosal/Meissner plexus", "why": "This plexus lies in submucosa and regulates mucosal functions."}, {"text": "Celiac plexus only", "why": "This extrinsic autonomic plexus does not replace the intrinsic submucosal network."}, {"text": "Myenteric/Auerbach plexus", "why": "This primarily coordinates muscular motility."}, {"text": "Choroid plexus", "why": "This produces CSF in ventricles."}, {"text": "Brachial plexus", "why": "This supplies upper limb."}], "answer": 0}, {"id": "Q051", "ref": "1.1-17", "deck": "1.1", "topic": "Sensory pathways", "stem": "Which finding is most consistent with primary injury to an anterior horn motor neuron?", "options": [{"text": "Focal weakness with atrophy and reduced reflexes", "why": "Anterior horn cells are lower motor neurons."}, {"text": "Sensory loss without any motor deficit", "why": "This favors a sensory pathway lesion rather than an anterior horn lesion."}, {"text": "Papilledema without motor findings", "why": "This suggests raised ICP rather than focal lower motor neuron loss."}, {"text": "Contralateral homonymous hemianopia", "why": "This implicates retrochiasmal visual pathways."}, {"text": "Isolated loss of smell", "why": "This implicates olfactory pathways."}], "answer": 0}, {"id": "Q052", "ref": "1.2-4", "deck": "1.2", "topic": "Skull", "stem": "How many bones make up the standard adult skull count, excluding auditory ossicles?", "options": [{"text": "14", "why": "This counts facial bones alone."}, {"text": "6", "why": "This counts auditory ossicles alone."}, {"text": "8", "why": "This counts neurocranial bones alone."}, {"text": "28", "why": "This includes the 6 auditory ossicles in addition to the standard 22."}, {"text": "22", "why": "There are 8 neurocranial and 14 facial bones."}], "answer": 4}, {"id": "Q053", "ref": "1.2-4", "deck": "1.2", "topic": "Skull", "stem": "Which bone belongs to the neurocranium rather than the facial skeleton?", "options": [{"text": "Inferior nasal concha", "why": "This is counted among facial bones."}, {"text": "Zygomatic", "why": "This is a facial bone."}, {"text": "Maxilla", "why": "This is a facial bone."}, {"text": "Sphenoid", "why": "Sphenoid contributes to the cranial base and lateral skull."}, {"text": "Vomer", "why": "This is a facial bone forming part of the nasal septum."}], "answer": 3}, {"id": "Q054", "ref": "1.2-5", "deck": "1.2", "topic": "Skull", "stem": "The anterior fontanelle is located at the future junction of the coronal and sagittal sutures. What is this landmark called?", "options": [{"text": "Pterion", "why": "Pterion is a lateral four-bone junction."}, {"text": "Asterion", "why": "Asterion joins parietal, occipital, and mastoid temporal regions."}, {"text": "Nasion", "why": "Nasion is at the frontonasal junction."}, {"text": "Lambda", "why": "Lambda is the sagittal-lambdoid junction."}, {"text": "Bregma", "why": "Bregma corresponds to this junction."}], "answer": 4}, {"id": "Q055", "ref": "1.2-5", "deck": "1.2", "topic": "Skull", "stem": "Which suture separates the two parietal bones?", "options": [{"text": "Coronal", "why": "This joins frontal to parietal bones."}, {"text": "Lambdoid", "why": "This joins parietal to occipital bone."}, {"text": "Sagittal", "why": "It runs in the midline between paired parietals."}, {"text": "Metopic", "why": "This separates developing frontal halves."}, {"text": "Squamous", "why": "This joins temporal and parietal regions laterally."}], "answer": 2}, {"id": "Q056", "ref": "1.2-5", "deck": "1.2", "topic": "Skull", "stem": "A radiologist identifies the junction of sagittal and lambdoid sutures. Which landmark is being described?", "options": [{"text": "Cribriform plate", "why": "This transmits olfactory axons in the anterior cranial base."}, {"text": "Bregma", "why": "This is the coronal-sagittal junction."}, {"text": "Lambda", "why": "The posterior fontanelle lies at this region in infancy."}, {"text": "Pterion", "why": "This lies laterally over the middle meningeal artery."}, {"text": "Sella turcica", "why": "This houses the pituitary gland."}], "answer": 2}, {"id": "Q057", "ref": "1.2-6", "deck": "1.2", "topic": "Skull", "stem": "Which bone forms the principal movable lower jaw and is visible on the anterior skull view?", "options": [{"text": "Maxilla", "why": "This forms the upper jaw."}, {"text": "Ethmoid", "why": "This contributes to anterior cranial base and nasal/orbital structures."}, {"text": "Occipital", "why": "This forms posterior skull and surrounds foramen magnum."}, {"text": "Mandible", "why": "The mandible is the movable lower jaw."}, {"text": "Parietal", "why": "This forms much of the cranial vault."}], "answer": 3}, {"id": "Q058", "ref": "1.2-7", "deck": "1.2", "topic": "Skull", "stem": "A 17-year-old boy is struck on the left side of the head during a baseball game. He briefly loses consciousness, then becomes alert enough to answer questions and describe the accident. During transport, he develops a worsening headache and vomits. In the emergency department he becomes progressively somnolent. Noncontrast CT demonstrates a left biconvex extra-axial hyperdense collection that stops at sutures, with underlying brain displaced medially. A fracture overlies the pterion. Which vessel is classically responsible for the bleeding?", "options": [{"text": "Middle meningeal artery", "why": "It runs deep to pterion and is the classic epidural bleeding source."}, {"text": "Bridging cortical vein", "why": "This is the classic source of subdural hematoma."}, {"text": "Anterior communicating artery", "why": "Its aneurysmal rupture causes SAH."}, {"text": "Basilar artery", "why": "This lies near ventral brainstem rather than beneath lateral calvaria."}, {"text": "Superior sagittal sinus", "why": "This is not the classic arterial source beneath pterion."}], "answer": 0}, {"id": "Q059", "ref": "1.2-8", "deck": "1.2", "topic": "Skull", "stem": "A groove runs along the internal midline of the cranial vault adjacent to arachnoid granulation impressions. Which venous structure occupies this region?", "options": [{"text": "Straight sinus", "why": "This lies at the falx-tentorium junction."}, {"text": "Cavernous sinus", "why": "This lies lateral to the sella."}, {"text": "Sigmoid sinus", "why": "This lies posterolaterally and drains to jugular vein."}, {"text": "Superior sagittal sinus", "why": "It runs along the superior attached border of falx under the vault."}, {"text": "Inferior sagittal sinus", "why": "This lies in the free inferior falx border."}], "answer": 3}, {"id": "Q060", "ref": "1.2-9", "deck": "1.2", "topic": "Skull", "stem": "A mass centered in the posterior cranial fossa most directly threatens which structures?", "options": [{"text": "Temporal poles only", "why": "These lie in the middle fossa."}, {"text": "Pituitary gland alone", "why": "This lies in the sella of the central skull base."}, {"text": "Facial bones and nasal conchae", "why": "These are not posterior fossa contents."}, {"text": "Frontal lobes only", "why": "These rest in the anterior fossa."}, {"text": "Cerebellum and brainstem", "why": "These occupy the posterior fossa."}], "answer": 4}, {"id": "Q061", "ref": "1.2-9", "deck": "1.2", "topic": "Skull", "stem": "Following anterior cranial base trauma, a patient has anosmia and clear nasal drainage. Injury to which structure best explains both findings?", "options": [{"text": "Hypoglossal canal", "why": "This transmits CN XII."}, {"text": "Cribriform plate", "why": "Olfactory axons cross it, and adjacent meningeal disruption can cause CSF rhinorrhea."}, {"text": "Foramen spinosum", "why": "This transmits middle meningeal vessels."}, {"text": "Internal acoustic meatus", "why": "This transmits VII/VIII and is associated with ear rather than olfactory pathways."}, {"text": "Foramen ovale", "why": "This transmits V3."}], "answer": 1}, {"id": "Q062", "ref": "1.2-10", "deck": "1.2", "topic": "Skull trauma", "stem": "After a motor vehicle collision, a patient has blood behind the tympanic membrane and bruising over the mastoid. Which diagnosis is most strongly suggested?", "options": [{"text": "Idiopathic intracranial hypertension", "why": "This does not produce trauma-associated bruising and middle-ear blood."}, {"text": "Normal pressure hydrocephalus", "why": "This is a chronic gait/cognition/bladder syndrome."}, {"text": "Isolated optic neuritis", "why": "This causes visual dysfunction rather than these trauma signs."}, {"text": "Basilar skull fracture", "why": "Hemotympanum and Battle sign support skull-base injury, often temporal."}, {"text": "Isolated nasal bone fracture", "why": "This does not explain hemotympanum and mastoid ecchymosis well."}], "answer": 3}, {"id": "Q063", "ref": "1.2-10", "deck": "1.2", "topic": "Skull trauma", "stem": "Clear fluid leaks from a patient's nose after a skull-base fracture. Which laboratory finding best supports that the fluid is CSF?", "options": [{"text": "Troponin elevation", "why": "This indicates myocardial injury rather than fluid identity."}, {"text": "Beta-2 transferrin", "why": "This is a useful confirmatory marker of a CSF leak."}, {"text": "Urinary nitrites", "why": "These are unrelated to nasal CSF identification."}, {"text": "High salivary amylase alone", "why": "This indicates salivary contribution rather than CSF specifically."}, {"text": "Serum bilirubin alone", "why": "This is not a specific CSF leakage marker."}], "answer": 1}, {"id": "Q064", "ref": "1.2-11", "deck": "1.2", "topic": "Skull trauma", "stem": "Which description corresponds to Battle sign?", "options": [{"text": "Loss of the corneal reflex", "why": "This is a cranial nerve reflex abnormality."}, {"text": "Bilateral optic disc swelling", "why": "This is papilledema."}, {"text": "Postauricular/mastoid ecchymosis", "why": "Bruising behind the ear is Battle sign."}, {"text": "A fixed dilated pupil", "why": "This can indicate compressive CN III dysfunction."}, {"text": "Periorbital ecchymosis", "why": "This is the raccoon-eye sign."}], "answer": 2}, {"id": "Q065", "ref": "1.2-13", "deck": "1.2", "topic": "Meninges", "stem": "Which pair forms the leptomeninges?", "options": [{"text": "Arachnoid and choroid plexus", "why": "Choroid plexus is specialized ventricular secretory tissue."}, {"text": "Pia and ependyma", "why": "Ependyma lines ventricular cavities and is not one of the meninges."}, {"text": "Arachnoid and pia", "why": "These are the two delicate inner meningeal layers."}, {"text": "Dura and skull", "why": "Skull is bone, and dura is pachymeninx."}, {"text": "Periosteal and meningeal dura", "why": "These are cranial dural layers."}], "answer": 2}, {"id": "Q066", "ref": "1.2-14", "deck": "1.2", "topic": "Meninges", "stem": "Which statement distinguishes spinal from cranial dura?", "options": [{"text": "Spinal dura has an additional intracranial periosteal layer", "why": "That layer is a feature of cranial dura."}, {"text": "Spinal dura is the continuation of the meningeal layer", "why": "Cranial dura has periosteal and meningeal layers; spinal dura lacks the cranial periosteal layer."}, {"text": "Spinal dura is absent below the conus", "why": "The dural sac extends to approximately S2."}, {"text": "Spinal dura directly produces most CSF", "why": "Choroid plexus is the main source."}, {"text": "Spinal dura follows every sulcus", "why": "Pia follows neural surface contours."}], "answer": 1}, {"id": "Q067", "ref": "1.2-14", "deck": "1.2", "topic": "Meninges", "stem": "Separation of cranial dural layers normally forms which structures?", "options": [{"text": "Dorsal root ganglia", "why": "These are peripheral sensory collections."}, {"text": "Lateral ventricles", "why": "These are cavities within cerebral hemispheres."}, {"text": "Cerebral aqueduct", "why": "This is a midbrain CSF channel."}, {"text": "Dural venous sinuses", "why": "These channels collect venous blood and absorbed CSF."}, {"text": "Submucosal plexus", "why": "This is an enteric neural network."}], "answer": 3}, {"id": "Q068", "ref": "1.2-15", "deck": "1.2", "topic": "Dural partitions", "stem": "Which dural fold separates cerebral hemispheres?", "options": [{"text": "Arachnoid trabecula", "why": "This crosses the subarachnoid space, not the cerebral midline as a dural fold."}, {"text": "Diaphragma sellae", "why": "This covers the pituitary fossa."}, {"text": "Tentorium cerebelli", "why": "This separates cerebrum from cerebellum."}, {"text": "Falx cerebelli", "why": "This partially separates cerebellar hemispheres."}, {"text": "Falx cerebri", "why": "This is the vertical interhemispheric dural partition."}], "answer": 4}, {"id": "Q069", "ref": "1.2-15", "deck": "1.2", "topic": "Dural partitions", "stem": "A lesion lies below the tentorium and above the foramen magnum. Which term best describes its compartment?", "options": [{"text": "Infratentorial", "why": "This refers to the posterior fossa below tentorium."}, {"text": "Supratentorial", "why": "This refers to above tentorium."}, {"text": "Intraventricular necessarily", "why": "The location alone does not mean within a ventricle."}, {"text": "Intramural", "why": "This describes location within an organ wall, not this cranial compartment."}, {"text": "Extracranial", "why": "The lesion is still inside the skull."}], "answer": 0}, {"id": "Q070", "ref": "1.2-15", "deck": "1.2", "topic": "Dural partitions", "stem": "Which dural structure roofs the sella turcica and contains an opening for the pituitary stalk?", "options": [{"text": "Falx cerebri", "why": "This separates cerebral hemispheres."}, {"text": "Falx cerebelli", "why": "This separates parts of the cerebellum."}, {"text": "Diaphragma sellae", "why": "This dural fold covers the pituitary fossa."}, {"text": "Choroid plexus", "why": "This is CSF-secreting ventricular tissue."}, {"text": "Ligamentum flavum", "why": "This is a spinal ligament."}], "answer": 2}, {"id": "Q071", "ref": "1.2-16", "deck": "1.2", "topic": "Meninges", "stem": "Irritation of supratentorial dura refers pain toward the forehead. Which nerve provides the principal sensory pathway?", "options": [{"text": "Optic nerve", "why": "CN II is visual sensory, not the main dural pain pathway."}, {"text": "Trigeminal nerve", "why": "CN V supplies most supratentorial dural sensation."}, {"text": "Facial motor nerve", "why": "CN VII chiefly supplies facial expression muscles through its motor component."}, {"text": "Pelvic splanchnic nerves", "why": "These are sacral parasympathetic routes."}, {"text": "Hypoglossal nerve", "why": "CN XII supplies tongue muscles."}], "answer": 1}, {"id": "Q072", "ref": "1.2-16", "deck": "1.2", "topic": "Meninges", "stem": "Posterior fossa dural irritation produces occipital and upper neck pain. Which nerves are important contributors?", "options": [{"text": "Lumbar nerves L4-L5", "why": "These do not supply cranial dura."}, {"text": "CN XII alone", "why": "This is primarily motor to tongue."}, {"text": "Median nerve", "why": "This is a peripheral upper-limb nerve."}, {"text": "CN II alone", "why": "Optic nerve does not explain occipital dural referral."}, {"text": "Upper cervical nerves C1-C3", "why": "These contribute substantially to posterior fossa dural sensation."}], "answer": 4}, {"id": "Q073", "ref": "1.2-17", "deck": "1.2", "topic": "Meninges", "stem": "Which membrane closely follows the gyri and descends into cerebral sulci?", "options": [{"text": "Tentorium", "why": "This is a broad dural fold."}, {"text": "Periosteal dura", "why": "This adheres to skull."}, {"text": "Arachnoid mater", "why": "Arachnoid bridges over sulci."}, {"text": "Ependyma", "why": "This lines ventricles rather than the brain surface."}, {"text": "Pia mater", "why": "Pia adheres directly to the neural surface."}], "answer": 4}, {"id": "Q074", "ref": "1.2-17", "deck": "1.2", "topic": "Meninges", "stem": "CSF is absorbed classically into the superior sagittal sinus through which structures?", "options": [{"text": "Dorsal root ganglia", "why": "These contain sensory neuron somata."}, {"text": "Arachnoid granulations", "why": "These project into venous sinuses and support CSF drainage."}, {"text": "Nodes of Ranvier", "why": "These support saltatory conduction."}, {"text": "Choroid plexus capillaries alone", "why": "Choroid plexus chiefly produces CSF."}, {"text": "Cerebral aqueduct epithelium only", "why": "The aqueduct conducts CSF between ventricles."}], "answer": 1}, {"id": "Q075", "ref": "1.2-18", "deck": "1.2", "topic": "Meningeal spaces", "stem": "Which meningeal compartment normally contains both CSF and large cerebral vessels?", "options": [{"text": "Subarachnoid space", "why": "This real space lies between arachnoid and pia."}, {"text": "Sympathetic ganglion", "why": "This is peripheral neural tissue."}, {"text": "Subdural space", "why": "This is normally a potential cleavage plane."}, {"text": "Space inside compact skull bone", "why": "This is not a meningeal CSF space."}, {"text": "Cranial epidural space", "why": "This is normally potential, without a normal CSF reservoir."}], "answer": 0}, {"id": "Q076", "ref": "1.2-18", "deck": "1.2", "topic": "Meningeal spaces", "stem": "Which statement is true of the spinal epidural space but not the normal cranial epidural potential space?", "options": [{"text": "It is between arachnoid and pia", "why": "That is subarachnoid space."}, {"text": "It normally contains fat and venous plexus", "why": "The spinal epidural space is normally real."}, {"text": "It is the main site of choroid plexus secretion", "why": "Choroid plexus lies within ventricles."}, {"text": "It is the usual site of berry aneurysm blood", "why": "Aneurysmal blood enters the cranial subarachnoid compartment."}, {"text": "It contains the cerebral aqueduct", "why": "The aqueduct is in midbrain."}], "answer": 1}, {"id": "Q077", "ref": "1.2-19", "deck": "1.2", "topic": "Intracranial hemorrhage", "stem": "An 81-year-old man is brought to clinic by his daughter because of three weeks of worsening confusion, slowed walking, and intermittent headache. He fell against a doorframe one month ago but did not seek care because he felt well at the time. He now has mild right arm weakness. Noncontrast CT shows a crescentic left extra-axial collection extending across several sutures, with mild midline shift. Age-related cerebral atrophy is also present. Injury to which vessel most likely initiated this process?", "options": [{"text": "Vertebral artery in the neck", "why": "This is not the typical source of chronic crescentic subdural blood."}, {"text": "Anterior communicating artery aneurysm", "why": "This causes subarachnoid blood and often thunderclap headache."}, {"text": "Middle meningeal artery", "why": "This classically causes lens-shaped epidural blood."}, {"text": "Central retinal artery", "why": "This supplies retina, not an extra-axial collection."}, {"text": "Bridging vein", "why": "Atrophy stretches bridging veins, predisposing to subdural bleeding."}], "answer": 4}, {"id": "Q078", "ref": "1.2-19", "deck": "1.2", "topic": "Intracranial hemorrhage", "stem": "A 43-year-old woman develops an explosive headache while lifting a heavy box. The pain reaches maximal intensity within seconds and is unlike her previous occasional tension headaches. She vomits and complains that flexing her neck worsens the pain. Blood pressure is elevated, and she is drowsy but follows commands. Noncontrast head CT shows hyperdense material tracking through the basal cisterns and several cortical sulci rather than forming a discrete lentiform or crescentic collection. Which diagnosis best explains this presentation?", "options": [{"text": "Optic neuritis", "why": "This causes painful visual loss rather than this CT pattern."}, {"text": "Epidural hematoma", "why": "This typically forms a focal biconvex collection after trauma."}, {"text": "Hydrocephalus ex vacuo", "why": "This is tissue-loss-associated ventriculomegaly, not acute cisternal blood."}, {"text": "Subarachnoid hemorrhage", "why": "Thunderclap headache and cisternal/sulcal blood are classic."}, {"text": "Chronic subdural hematoma", "why": "This typically forms a crescentic extra-axial collection."}], "answer": 3}, {"id": "Q079", "ref": "1.2-20", "deck": "1.2", "topic": "Intracranial hemorrhage", "stem": "Why does a typical cranial epidural hematoma stop at skull sutures?", "options": [{"text": "All epidural blood is inside a ventricle", "why": "Epidural blood is outside dura."}, {"text": "CSF cannot cross the cerebral aqueduct", "why": "Aqueduct flow does not define epidural boundaries."}, {"text": "Pia attaches to sutures", "why": "Pia adheres to brain, not skull sutures."}, {"text": "Bridging veins form a complete sutural wall", "why": "The limiting attachment is dural, not a vein wall."}, {"text": "Dura adheres firmly at sutures", "why": "These attachments limit the skull-dura collection."}], "answer": 4}, {"id": "Q080", "ref": "1.2-20", "deck": "1.2", "topic": "Intracranial hemorrhage", "stem": "Which CT description most strongly favors subdural over epidural hematoma?", "options": [{"text": "Blood confined to basal cisterns", "why": "This favors SAH."}, {"text": "Biconvex blood bounded by sutures", "why": "This favors epidural hematoma."}, {"text": "Isolated enlargement of the third ventricle", "why": "This suggests a CSF-flow issue rather than extra-axial blood."}, {"text": "Proportional enlargement of ventricles and cortical sulci", "why": "This favors atrophy/ex vacuo."}, {"text": "Crescentic blood crossing sutures but limited by dural folds", "why": "This is the classic subdural distribution."}], "answer": 4}, {"id": "Q081", "ref": "1.2-21", "deck": "1.2", "topic": "Herniation", "stem": "After a left temporal mass expands, the patient becomes obtunded and the left pupil becomes fixed and dilated. Which structure is being compressed early?", "options": [{"text": "Left CN III", "why": "Uncal herniation compresses ipsilateral pupilloconstrictor fibers of CN III."}, {"text": "Right CN VI", "why": "This does not directly control left pupil constriction."}, {"text": "Left optic nerve alone", "why": "This affects afferent vision rather than producing the classic ipsilateral compressive efferent pupil sign."}, {"text": "Left facial nerve", "why": "CN VII does not provide pupillary constriction."}, {"text": "Right pelvic splanchnic nerve", "why": "This is a pelvic autonomic structure."}], "answer": 0}, {"id": "Q082", "ref": "1.2-21", "deck": "1.2", "topic": "Herniation", "stem": "A large right hemispheric mass pushes the cingulate gyrus beneath the falx. Compression of which artery may cause new left leg-predominant weakness?", "options": [{"text": "Middle meningeal artery", "why": "This supplies dura rather than medial motor cortex."}, {"text": "Anterior cerebral artery", "why": "ACA supplies medial motor cortex representing the contralateral leg."}, {"text": "Central retinal artery", "why": "This supplies retina."}, {"text": "Posterior inferior cerebellar artery", "why": "This supplies cerebellar/medullary territories."}, {"text": "Basilar artery alone", "why": "This supplies posterior circulation brainstem territories rather than the classic subfalcine medial cortex."}], "answer": 1}, {"id": "Q083", "ref": "1.2-21", "deck": "1.2", "topic": "Herniation", "stem": "A posterior fossa mass forces the cerebellar tonsils through the foramen magnum. Which complication is most immediately feared?", "options": [{"text": "Isolated loss of parotid secretion", "why": "This is not the life-threatening consequence of medullary compression."}, {"text": "Improved CSF absorption", "why": "Herniation can instead obstruct CSF flow."}, {"text": "Selective CN I injury without other deficits", "why": "The olfactory nerve is remote from this opening."}, {"text": "Pure arm dermatome sensory loss", "why": "This does not describe brainstem compression."}, {"text": "Medullary compression with respiratory failure", "why": "Tonsillar herniation threatens vital brainstem centers."}], "answer": 4}, {"id": "Q084", "ref": "1.2-21", "deck": "1.2", "topic": "Herniation", "stem": "A left uncal herniation causes left hemiparesis because the opposite cerebral peduncle is compressed against the tentorium. What explains this atypical laterality?", "options": [{"text": "Normal uncrossed organization of all corticospinal fibers", "why": "Most corticospinal fibers cross in caudal medulla."}, {"text": "A dorsal root ganglion lesion", "why": "This would primarily cause segmental sensory symptoms."}, {"text": "A right celiac ganglion lesion", "why": "This is an abdominal autonomic structure."}, {"text": "Kernohan notch phenomenon", "why": "Contralateral peduncle compression creates weakness ipsilateral to the mass."}, {"text": "A pure left optic nerve lesion", "why": "This does not explain limb weakness."}], "answer": 3}, {"id": "Q085", "ref": "1.2-23", "deck": "1.2", "topic": "Ventricular anatomy", "stem": "Which cells normally line the cerebral ventricles?", "options": [{"text": "Satellite cells", "why": "These surround peripheral ganglion somata."}, {"text": "Schwann cells", "why": "These ensheath peripheral axons."}, {"text": "Ependymal cells", "why": "These line ventricles and central canal."}, {"text": "Skeletal myocytes", "why": "These form skeletal muscle."}, {"text": "Osteoblasts", "why": "These form bone."}], "answer": 2}, {"id": "Q086", "ref": "1.2-24", "deck": "1.2", "topic": "Ventricular anatomy", "stem": "The inferior horn of a lateral ventricle extends into which cerebral lobe?", "options": [{"text": "Cerebellar hemisphere", "why": "Lateral ventricles lie in cerebral hemispheres."}, {"text": "Temporal", "why": "The inferior horn is the temporal horn."}, {"text": "Medulla", "why": "This is part of brainstem adjacent to fourth ventricle."}, {"text": "Occipital", "why": "This contains the posterior horn."}, {"text": "Frontal", "why": "This contains the anterior horn."}], "answer": 1}, {"id": "Q087", "ref": "1.2-24", "deck": "1.2", "topic": "Ventricular anatomy", "stem": "Each lateral ventricle communicates directly with the third through which opening?", "options": [{"text": "Cerebral aqueduct", "why": "This connects third to fourth."}, {"text": "Foramen of Magendie", "why": "This is the median fourth-ventricle outlet."}, {"text": "Foramen of Luschka", "why": "These are lateral fourth-ventricle outlets."}, {"text": "Foramen spinosum", "why": "This is a skull opening for meningeal vessels."}, {"text": "Interventricular foramen of Monro", "why": "There is an opening from each lateral ventricle to the third."}], "answer": 4}, {"id": "Q088", "ref": "1.2-25", "deck": "1.2", "topic": "Ventricular anatomy", "stem": "Which cavity lies between the thalami?", "options": [{"text": "Inferior horn of lateral ventricle", "why": "This extends into temporal lobe."}, {"text": "Third ventricle", "why": "The third is the midline diencephalic ventricle."}, {"text": "Cisterna magna", "why": "This is a subarachnoid cistern below cerebellum."}, {"text": "Fourth ventricle", "why": "This lies between brainstem and cerebellum."}, {"text": "Central canal of spinal cord", "why": "This lies within spinal gray matter."}], "answer": 1}, {"id": "Q089", "ref": "1.2-25", "deck": "1.2", "topic": "Ventricular anatomy", "stem": "Which channel connects the third and fourth ventricles and passes through the midbrain?", "options": [{"text": "Foramen of Monro", "why": "This connects lateral and third ventricles."}, {"text": "Foramen ovale", "why": "This transmits V3 through skull."}, {"text": "Superior sagittal sinus", "why": "This is venous drainage."}, {"text": "Cerebral aqueduct", "why": "This narrow channel is vulnerable to obstruction."}, {"text": "Central canal in lumbar cord", "why": "This is caudal to the fourth ventricle."}], "answer": 3}, {"id": "Q090", "ref": "1.2-25", "deck": "1.2", "topic": "Ventricular anatomy", "stem": "CSF leaves the fourth ventricle through one median and two lateral apertures. Which pairing is correct?", "options": [{"text": "Median aqueduct; lateral central canals", "why": "Aqueduct is the inlet from third, and there are not paired lateral central-canal outlets."}, {"text": "Median Monro; lateral Magendie", "why": "Monro is between lateral and third ventricles."}, {"text": "Median Luschka; lateral Monro", "why": "This reverses outlet names and misplaces Monro."}, {"text": "Median spinosum; lateral ovale", "why": "These are skull foramina, not ventricular outlets."}, {"text": "Median Magendie; lateral Luschka", "why": "These are the fourth ventricular outlets."}], "answer": 4}, {"id": "Q091", "ref": "1.2-26", "deck": "1.2", "topic": "CSF physiology", "stem": "What is the principal site of CSF production?", "options": [{"text": "Superior sagittal sinus", "why": "This receives venous blood and absorbed CSF."}, {"text": "Schwann cells", "why": "These support peripheral axons."}, {"text": "Arachnoid granulations", "why": "These chiefly mediate drainage."}, {"text": "Dural venous sinus endothelium", "why": "This is not the principal CSF secretory epithelium."}, {"text": "Choroid plexus", "why": "Specialized choroid epithelial cells secrete most CSF."}], "answer": 4}, {"id": "Q092", "ref": "1.2-26", "deck": "1.2", "topic": "CSF physiology", "stem": "Which sequence correctly follows CSF from the third ventricle to venous drainage?", "options": [{"text": "Superior sagittal sinus → aqueduct → fourth", "why": "The venous sinus is a drainage endpoint rather than the usual source."}, {"text": "Aqueduct → fourth → apertures → subarachnoid space → arachnoid granulations", "why": "This is the classical outflow route."}, {"text": "Fourth → aqueduct → lateral → celiac ganglion", "why": "This reverses flow and adds a peripheral ganglion."}, {"text": "Pia → dorsal root → central canal → carotid artery", "why": "This is not the CSF circulation pathway."}, {"text": "Monro → lateral → white ramus → vein", "why": "Monro leads upstream to lateral ventricles, and white rami are nerves."}], "answer": 1}, {"id": "Q093", "ref": "1.2-26", "deck": "1.2", "topic": "CSF physiology", "stem": "Which major function of CSF reduces the effective weight exerted by the brain on its base?", "options": [{"text": "Generation of all action potentials", "why": "Neuronal membranes generate action potentials."}, {"text": "Buoyancy", "why": "CSF supports the brain by flotation."}, {"text": "Secretion of thyroid hormone", "why": "This is an endocrine function unrelated to CSF buoyancy."}, {"text": "Somatic muscle contraction", "why": "This is a motor-neuron function."}, {"text": "Myelin production", "why": "This is a glial function."}], "answer": 1}, {"id": "Q094", "ref": "1.2-27", "deck": "1.2", "topic": "Hydrocephalus", "stem": "An infant's head circumference rapidly crosses percentiles and the anterior fontanelle bulges. Imaging shows ventricular enlargement. Which mechanism is a rare cause of this condition?", "options": [{"text": "CSF overproduction by a choroid plexus papilloma", "why": "Overproduction is uncommon compared with obstruction or impaired absorption."}, {"text": "Isolated facial muscle denervation", "why": "This does not cause ventricular enlargement."}, {"text": "Physiologic closure of a peripheral nerve", "why": "Peripheral nerves do not normally close to regulate CSF."}, {"text": "Loss of all arachnoid without any change in outflow", "why": "The proposed unchanged outflow does not explain accumulating CSF."}, {"text": "Decreased CSF production alone", "why": "This does not explain excess ventricular fluid."}], "answer": 0}, {"id": "Q095", "ref": "1.2-28", "deck": "1.2", "topic": "Hydrocephalus", "stem": "Weeks after subarachnoid hemorrhage, a patient develops enlargement of all ventricles without an intraventricular block. Which mechanism is most likely?", "options": [{"text": "Aqueduct stenosis", "why": "This spares the fourth ventricle downstream."}, {"text": "Impaired CSF absorption after outflow scarring", "why": "Blood can disrupt arachnoid/subarachnoid resorption, producing communicating hydrocephalus."}, {"text": "Brain atrophy necessarily", "why": "The posthemorrhagic outflow problem better explains the described hydrocephalus."}, {"text": "Decreased choroid plexus secretion", "why": "This would not cause CSF accumulation."}, {"text": "Isolated obstruction of one foramen of Monro", "why": "This preferentially enlarges the corresponding lateral ventricle."}], "answer": 1}, {"id": "Q096", "ref": "1.2-29", "deck": "1.2", "topic": "Hydrocephalus", "stem": "A cyst blocks only the right foramen of Monro. Which cavity is expected to dilate first and most directly?", "options": [{"text": "Right lateral ventricle", "why": "It lies immediately upstream of the obstruction."}, {"text": "Cisterna magna only", "why": "This is outside the ventricular system downstream."}, {"text": "Left lateral ventricle only", "why": "Its own foramen remains patent."}, {"text": "Fourth ventricle only", "why": "This lies downstream."}, {"text": "All ventricles equally", "why": "A unilateral proximal block does not directly obstruct every cavity."}], "answer": 0}, {"id": "Q097", "ref": "1.2-29", "deck": "1.2", "topic": "Hydrocephalus", "stem": "Imaging shows enlargement of both lateral ventricles and the third ventricle, with a normal-sized fourth ventricle. Where is the most likely obstruction?", "options": [{"text": "Cerebral aqueduct", "why": "The blockage is between third and fourth."}, {"text": "Right foramen of Monro alone", "why": "This usually enlarges only the right lateral ventricle."}, {"text": "Superior sagittal sinus with no other effect", "why": "This would be a downstream drainage issue rather than the specific third-fourth bottleneck."}, {"text": "Arachnoid granulations", "why": "Impaired resorption generally affects the entire ventricular system."}, {"text": "Both lateral fourth-ventricle apertures alone", "why": "An outlet obstruction usually also enlarges the fourth."}], "answer": 0}, {"id": "Q098", "ref": "1.2-29", "deck": "1.2", "topic": "Hydrocephalus", "stem": "A tumor blocks all fourth ventricular outlets. Which pattern is expected?", "options": [{"text": "Only cortical sulci enlarge due to neuronal loss", "why": "This describes atrophy rather than outlet obstruction."}, {"text": "Only the right lateral ventricle enlarges", "why": "This suggests right Monro obstruction."}, {"text": "Dilation of lateral and third only with fourth spared", "why": "This is the classic aqueduct pattern."}, {"text": "No ventricular dilation can occur", "why": "An outlet block can produce obstructive hydrocephalus."}, {"text": "Dilation upstream including the fourth ventricle", "why": "The outlet bottleneck is distal to the fourth cavity."}], "answer": 4}, {"id": "Q099", "ref": "1.2-31", "deck": "1.2", "topic": "Hydrocephalus", "stem": "A child with aqueductal stenosis undergoes endoscopic third ventriculostomy. What is the purpose of the opening?", "options": [{"text": "Connect lateral ventricle to nasal cavity", "why": "That would be an abnormal leak, not the intended route."}, {"text": "Increase CSF production by choroid plexus", "why": "The procedure creates drainage rather than more production."}, {"text": "Divert CSF from third ventricle to basal subarachnoid cisterns", "why": "This bypasses the blocked aqueduct in selected cases."}, {"text": "Drain directly into the sympathetic chain", "why": "The chain is neural tissue rather than a CSF destination."}, {"text": "Ablate all arachnoid granulations", "why": "These are needed for outflow/absorption."}], "answer": 2}, {"id": "Q100", "ref": "1.2-32", "deck": "1.2", "topic": "Congenital malformations", "stem": "A newborn is evaluated after prenatal imaging detected an open lumbosacral neural tube defect. Examination confirms myelomeningocele, and over the following days the infant develops an enlarging head circumference, feeding difficulty, and a weak cry. MRI shows a small crowded posterior fossa with downward displacement of cerebellar and brainstem structures and impaired CSF flow. The lateral ventricles are enlarged. Which congenital malformation is most strongly associated with this combination of spinal defect, hindbrain displacement, and hydrocephalus?", "options": [{"text": "Idiopathic intracranial hypertension", "why": "This does not explain the spinal defect and hindbrain displacement."}, {"text": "Hydrocephalus ex vacuo", "why": "This reflects tissue loss, not this congenital hindbrain pattern."}, {"text": "Chiari I alone", "why": "This usually presents later with low tonsils and lacks the typical myelomeningocele association."}, {"text": "Dandy-Walker malformation", "why": "This features enlarged posterior fossa and vermian hypoplasia."}, {"text": "Chiari II malformation", "why": "This combination strongly supports Chiari II."}], "answer": 4}, {"id": "Q101", "ref": "1.2-32", "deck": "1.2", "topic": "Congenital malformations", "stem": "A young adult has occipital headaches worsened by coughing. MRI shows low cerebellar tonsils and a cervical syrinx without myelomeningocele. Which disorder best fits?", "options": [{"text": "Chiari II malformation", "why": "This strongly associates with myelomeningocele and broader hindbrain displacement."}, {"text": "Normal pressure hydrocephalus", "why": "This is usually an older-adult gait/bladder/cognition syndrome."}, {"text": "Chiari I malformation", "why": "Later presentation with tonsillar descent and possible syringomyelia is classic."}, {"text": "Chronic subdural hematoma", "why": "This is an extra-axial collection rather than the described malformation."}, {"text": "Dandy-Walker malformation", "why": "This has vermian hypoplasia and enlarged posterior fossa."}], "answer": 2}, {"id": "Q102", "ref": "1.2-33", "deck": "1.2", "topic": "Congenital malformations", "stem": "A 2-month-old infant is referred because of increasing head circumference and delayed head control. The anterior fontanelle is full, and imaging demonstrates hydrocephalus. Sagittal MRI shows an enlarged posterior fossa, marked hypoplasia of the cerebellar vermis, and a cystic space continuous with an expanded fourth ventricle. The tentorium is elevated. There is no myelomeningocele, and the hindbrain does not have the crowded downward-displacement pattern of Chiari II. Which diagnosis best accounts for these anatomical findings?", "options": [{"text": "Chiari II malformation", "why": "Its posterior fossa is crowded/small with hindbrain descent."}, {"text": "Isolated aqueduct stenosis", "why": "The fourth ventricle is typically spared."}, {"text": "Dandy-Walker malformation", "why": "These are its characteristic anatomical features."}, {"text": "IIH", "why": "This usually has no hydrocephalus or congenital vermian defect."}, {"text": "Ex vacuo enlargement", "why": "This is compensatory expansion after tissue loss."}], "answer": 2}, {"id": "Q103", "ref": "1.2-33", "deck": "1.2", "topic": "Congenital malformations", "stem": "Which feature most clearly distinguishes Dandy-Walker malformation from the typical Chiari II pattern?", "options": [{"text": "Enlarged posterior fossa", "why": "Dandy-Walker enlarges the fossa; Chiari II crowds it."}, {"text": "CSF production in choroid plexus", "why": "This is normal physiology in both."}, {"text": "Hydrocephalus alone", "why": "Both can produce hydrocephalus."}, {"text": "Vomiting alone", "why": "This is nonspecific and can occur in either."}, {"text": "Infant presentation alone", "why": "Both can present in infancy."}], "answer": 0}, {"id": "Q104", "ref": "1.2-35", "deck": "1.2", "topic": "Pressure disorders", "stem": "A 26-year-old woman with obesity reports six weeks of daily headache, a pulse-synchronous whooshing sound in both ears, and brief episodes of dimmed vision when bending forward. Funduscopic examination shows bilateral papilledema. She has horizontal diplopia but no other focal weakness or sensory loss. MRI and venous imaging show no mass lesion, hydrocephalus, or venous sinus thrombosis; the ventricles are normal-sized. CSF cell count, glucose, and protein are normal. Which additional finding would best support idiopathic intracranial hypertension?", "options": [{"text": "Proportional cortical and ventricular atrophy", "why": "This favors ex vacuo changes."}, {"text": "Cystically enlarged fourth ventricle and absent vermis", "why": "This suggests Dandy-Walker."}, {"text": "Marked neutrophilic pleocytosis and low glucose", "why": "This suggests bacterial meningitis."}, {"text": "Only a normal opening pressure as the defining finding", "why": "IIH requires evidence of elevated pressure in the usual diagnostic framework."}, {"text": "Elevated LP opening pressure", "why": "High pressure with normal CSF and exclusion of secondary causes supports IIH."}], "answer": 4}, {"id": "Q105", "ref": "1.2-35", "deck": "1.2", "topic": "Pressure disorders", "stem": "A patient with confirmed IIH starts acetazolamide. What is its relevant mechanism?", "options": [{"text": "Direct closure of arachnoid granulations", "why": "Closing drainage would worsen CSF accumulation."}, {"text": "Destruction of oligodendrocytes", "why": "This would injure CNS myelin."}, {"text": "Selective dilation of the cerebral aqueduct by muscle relaxation", "why": "The aqueduct has no such therapeutic muscular mechanism."}, {"text": "Carbonic anhydrase inhibition reducing CSF secretion", "why": "This reduces choroid plexus fluid production."}, {"text": "Nicotinic receptor blockade at skeletal muscle", "why": "This would impair neuromuscular transmission."}], "answer": 3}, {"id": "Q106", "ref": "1.2-35", "deck": "1.2", "topic": "Pressure disorders", "stem": "Raised ICP produces horizontal diplopia through a false-localizing cranial neuropathy. Which nerve is commonly affected?", "options": [{"text": "CN VI", "why": "Abducens palsy impairs lateral rectus, causing horizontal diplopia."}, {"text": "CN I", "why": "Olfactory injury affects smell."}, {"text": "CN XII", "why": "This affects tongue movement."}, {"text": "CN IX alone", "why": "This is not the typical raised-pressure ocular-motor palsy."}, {"text": "CN VIII", "why": "This affects hearing and balance."}], "answer": 0}, {"id": "Q107", "ref": "1.2-36", "deck": "1.2", "topic": "Pressure disorders", "stem": "A 74-year-old retired teacher has nine months of progressive difficulty initiating walking and turning. His spouse reports that his feet appear stuck to the floor, followed more recently by urinary urgency and slowed thinking. Examination shows a broad-based short-stepped gait without a prominent resting tremor. MRI reveals enlargement of the lateral ventricles out of proportion to cortical sulcal widening, without a focal ventricular obstruction. Lumbar puncture performed after imaging yields a normal opening pressure at that measurement. Which diagnosis best integrates these findings?", "options": [{"text": "IIH", "why": "This more typically causes pressure/visual symptoms without ventricular enlargement."}, {"text": "Acute epidural hematoma", "why": "This is a traumatic extra-axial collection."}, {"text": "Ex vacuo enlargement", "why": "This is proportional to tissue loss and sulcal widening."}, {"text": "Isolated optic neuritis", "why": "This does not explain the triad."}, {"text": "Normal pressure hydrocephalus", "why": "The gait/bladder/cognition pattern and disproportionate ventriculomegaly fit NPH."}], "answer": 4}, {"id": "Q108", "ref": "1.2-36", "deck": "1.2", "topic": "Pressure disorders", "stem": "Which symptom most often appears first in the classic NPH syndrome?", "options": [{"text": "Acute monocular blindness", "why": "This is not the characteristic initial NPH symptom."}, {"text": "Hemotympanum", "why": "This suggests skull trauma."}, {"text": "Thunderclap headache", "why": "This suggests SAH rather than the usual NPH onset."}, {"text": "Ascending areflexic paralysis", "why": "This suggests a peripheral polyradiculoneuropathy."}, {"text": "Gait disturbance", "why": "Gait dysfunction typically precedes marked cognitive and urinary symptoms."}], "answer": 4}, {"id": "Q109", "ref": "1.2-36", "deck": "1.2", "topic": "Pressure disorders", "stem": "A patient with suspected NPH walks faster after a large-volume CSF tap. Which intervention may provide sustained benefit in a suitable candidate?", "options": [{"text": "Routine middle meningeal artery repair", "why": "This treats a different bleeding problem."}, {"text": "Resection of all cerebellar tonsils in every patient", "why": "NPH is not automatically caused by tonsillar descent."}, {"text": "Acetylcholinesterase inhibition as the defining curative procedure", "why": "This does not correct the CSF disorder."}, {"text": "Ablation of spinal dorsal root ganglia", "why": "This would damage sensation without treating CSF dynamics."}, {"text": "Ventriculoperitoneal shunt", "why": "A drainage response supports potential benefit from CSF diversion."}], "answer": 4}, {"id": "Q110", "ref": "1.2-37", "deck": "1.2", "topic": "Pressure disorders", "stem": "A patient with longstanding neurodegeneration has enlarged ventricles and proportionally widened cortical sulci without pressure symptoms. What best explains the imaging?", "options": [{"text": "Hydrocephalus ex vacuo", "why": "Tissue loss causes compensatory ventricular and sulcal enlargement."}, {"text": "CSF hypersecretion necessarily", "why": "Atrophy explains this pattern without overproduction."}, {"text": "IIH", "why": "This typically has normal ventricular size and elevated pressure."}, {"text": "Aqueductal obstruction", "why": "This produces an upstream ventricular pattern rather than proportional sulcal atrophy."}, {"text": "Acute tonsillar herniation", "why": "This is brainstem-threatening displacement rather than chronic proportional atrophy."}], "answer": 0}, {"id": "Q111", "ref": "1.2-37", "deck": "1.2", "topic": "Pressure disorders", "stem": "Which imaging finding favors NPH over ex vacuo ventricular enlargement?", "options": [{"text": "Crescentic extra-axial blood", "why": "This indicates subdural hematoma."}, {"text": "Blood throughout basal cisterns", "why": "This indicates SAH."}, {"text": "Ventricular dilation out of proportion to cortical sulcal widening", "why": "Disproportion is a key NPH clue in the appropriate syndrome."}, {"text": "Diffuse proportional widening of sulci and ventricles", "why": "This favors atrophy/ex vacuo."}, {"text": "Isolated fourth ventricular cyst with absent vermis", "why": "This favors Dandy-Walker."}], "answer": 2}, {"id": "Q112", "ref": "board-autonomic", "deck": "board", "topic": "Board integration", "stem": "A lesion interrupts sympathetic innervation to the right eye. Which finding is expected?", "options": [{"text": "Right fixed dilated pupil", "why": "This suggests parasympathetic dysfunction such as compressive CN III injury."}, {"text": "Bilateral papilledema necessarily", "why": "Raised ICP is not a necessary consequence of a focal sympathetic lesion."}, {"text": "Left miosis only as a required finding", "why": "The sympathetic eye deficit is typically ipsilateral."}, {"text": "Complete loss of accommodation from CN III destruction", "why": "This describes a different efferent pathway."}, {"text": "Right miosis with mild ptosis", "why": "Horner syndrome follows ipsilateral ocular sympathetic interruption."}], "answer": 4}, {"id": "Q113", "ref": "board-autonomic", "deck": "board", "topic": "Board integration", "stem": "After pelvic surgery, a man cannot contract the detrusor effectively during voiding. Injury to which efferent pathway best explains this?", "options": [{"text": "CN IX input", "why": "This serves head/neck parasympathetic functions."}, {"text": "Sympathetic beta-3 input alone", "why": "This promotes storage by relaxing detrusor."}, {"text": "Pelvic parasympathetic S2-S4", "why": "Parasympathetic input promotes detrusor contraction."}, {"text": "Cervical gray ramus", "why": "This distributes upper-body sympathetic fibers."}, {"text": "Pudendal somatic input to external sphincter", "why": "This controls the external sphincter rather than detrusor contraction."}], "answer": 2}, {"id": "Q114", "ref": "board-autonomic", "deck": "board", "topic": "Board integration", "stem": "A drug selectively activates beta-1 receptors. Which response is most expected?", "options": [{"text": "Direct skeletal muscle endplate depolarization", "why": "This requires nicotinic muscle receptors."}, {"text": "Increased heart rate and contractility", "why": "Cardiac beta-1 activation increases these functions."}, {"text": "Pupillary constriction", "why": "This is primarily muscarinic parasympathetic activity."}, {"text": "Reduced cardiac rate via M2 activation", "why": "The drug targets beta-1 rather than M2."}, {"text": "Loss of all ganglionic transmission", "why": "This would require ganglionic receptor blockade, not beta-1 activation."}], "answer": 1}, {"id": "Q115", "ref": "board-autonomic", "deck": "board", "topic": "Board integration", "stem": "Which receptor mediates postganglionic parasympathetic slowing of sinoatrial node rate?", "options": [{"text": "Nicotinic Nn alone", "why": "This mediates ganglionic transmission upstream."}, {"text": "Beta-2", "why": "This mediates smooth-muscle relaxation in sites such as bronchi."}, {"text": "Alpha-1", "why": "This primarily mediates smooth-muscle contraction including vascular constriction."}, {"text": "Nicotinic Nm", "why": "This is the skeletal muscle endplate receptor."}, {"text": "Muscarinic M2", "why": "Cardiac parasympathetic effector signaling chiefly uses M2."}], "answer": 4}, {"id": "Q116", "ref": "board-localization", "deck": "board", "topic": "Board integration", "stem": "Several months after a right internal capsule infarct, a patient has left-sided weakness, increased tone, brisk reflexes, and an extensor plantar response. Which localization category fits?", "options": [{"text": "Upper motor neuron pathway", "why": "These chronic signs reflect descending CNS motor injury above the pyramidal crossing."}, {"text": "Left anterior horn cell alone", "why": "This produces lower motor neuron signs."}, {"text": "Neuromuscular junction alone", "why": "This does not produce a classic Babinski/hyperreflexic pattern."}, {"text": "Primary muscle injury only", "why": "This does not explain an extensor plantar response."}, {"text": "Left dorsal root alone", "why": "This would be a segmental sensory lesion."}], "answer": 0}, {"id": "Q117", "ref": "board-localization", "deck": "board", "topic": "Board integration", "stem": "A right lateral corticospinal tract lesion at T8 causes weakness below the lesion on which side?", "options": [{"text": "Both arms only", "why": "T8 cord lies below upper-limb motor outflow."}, {"text": "Face only", "why": "Facial motor pathways are not in the T8 corticospinal tract."}, {"text": "Neither side because the tract is sensory", "why": "The corticospinal tract is motor."}, {"text": "Right", "why": "These fibers already crossed in the caudal medulla."}, {"text": "Left", "why": "Contralateral weakness is typical of lesions above the crossing."}], "answer": 3}, {"id": "Q118", "ref": "board-skull", "deck": "board", "topic": "Board integration", "stem": "Which skull opening transmits the middle meningeal artery?", "options": [{"text": "Foramen rotundum", "why": "This transmits V2."}, {"text": "Optic canal", "why": "This transmits II and ophthalmic artery."}, {"text": "Hypoglossal canal", "why": "This transmits XII."}, {"text": "Foramen ovale", "why": "This transmits V3."}, {"text": "Foramen spinosum", "why": "This is the classic entry of middle meningeal vessels."}], "answer": 4}, {"id": "Q119", "ref": "board-skull", "deck": "board", "topic": "Board integration", "stem": "A facial infection spreads to the cavernous sinus, producing ophthalmoplegia. Which nerve runs within the sinus near the internal carotid artery rather than in its lateral wall?", "options": [{"text": "CN VI", "why": "Abducens runs centrally beside the carotid and is vulnerable to sinus disease."}, {"text": "CN III", "why": "Oculomotor runs in the lateral wall."}, {"text": "CN IV", "why": "Trochlear runs in the lateral wall."}, {"text": "CN V2", "why": "Maxillary division runs in the lateral wall."}, {"text": "CN V1", "why": "Ophthalmic division runs in the lateral wall."}], "answer": 0}, {"id": "Q120", "ref": "board-skull", "deck": "board", "topic": "Board integration", "stem": "A dural-based mass has whorled cells and psammoma bodies. Which cell lineage is most closely associated with this tumor?", "options": [{"text": "Adrenal chromaffin cells", "why": "These produce catecholamines and can form pheochromocytoma."}, {"text": "Skeletal myocytes", "why": "These are not the meningioma lineage."}, {"text": "Schwann cells", "why": "These produce schwannoma."}, {"text": "Oligodendrocytes", "why": "These are CNS myelin cells associated with a different tumor lineage."}, {"text": "Arachnoid-associated meningothelial cells", "why": "These give rise to meningioma."}], "answer": 4}, {"id": "Q121", "ref": "board-hemorrhage", "deck": "board", "topic": "Board integration", "stem": "A patient recovering from aneurysmal SAH receives nimodipine. What is the principal intended neurologic benefit?", "options": [{"text": "Reconstitute peripheral myelin", "why": "This is not its action."}, {"text": "Repair the aneurysm mechanically", "why": "Definitive repair requires endovascular or surgical treatment."}, {"text": "Reduce delayed ischemic injury", "why": "Nimodipine improves outcomes after aneurysmal SAH related to delayed ischemia."}, {"text": "Raise CSF production to overcome hydrocephalus", "why": "Increasing CSF is not the goal."}, {"text": "Replace missing cerebellar vermis", "why": "A drug cannot reconstruct this congenital structure."}], "answer": 2}, {"id": "Q122", "ref": "board-hemorrhage", "deck": "board", "topic": "Board integration", "stem": "A patient has a mean arterial pressure of 90 mm Hg and an ICP of 30 mm Hg. What is the approximate cerebral perfusion pressure?", "options": [{"text": "60 mm Hg", "why": "CPP is approximately MAP minus ICP: 90-30."}, {"text": "90 mm Hg", "why": "This ignores intracranial pressure."}, {"text": "3 mm Hg", "why": "This divides the pressures instead of subtracting."}, {"text": "120 mm Hg", "why": "This incorrectly adds MAP and ICP."}, {"text": "30 mm Hg", "why": "This equals ICP, not CPP."}], "answer": 0}, {"id": "Q123", "ref": "board-hemorrhage", "deck": "board", "topic": "Board integration", "stem": "A deteriorating patient with a large intracranial mass develops hypertension, bradycardia, and irregular breathing. What is this combination called?", "options": [{"text": "Battle sign", "why": "This is mastoid ecchymosis after skull-base injury."}, {"text": "Albuminocytologic dissociation", "why": "This is a CSF protein/cell pattern."}, {"text": "Horner syndrome", "why": "This comprises miosis, ptosis, and variable anhidrosis."}, {"text": "Cushing response", "why": "This classic triad signals severe intracranial pressure/brainstem compromise."}, {"text": "NPH triad", "why": "This comprises gait, cognition, and urinary dysfunction."}], "answer": 3}, {"id": "Q124", "ref": "board-barriers", "deck": "board", "topic": "Board integration", "stem": "Which structure forms the main physical blood-brain barrier seal?", "options": [{"text": "Fenestrations in choroid capillaries", "why": "Fenestrations permit exchange rather than forming the BBB seal."}, {"text": "Synaptic clefts between cortical neurons", "why": "These are signaling junctions, not vascular barrier seals."}, {"text": "Tight junctions between ordinary Schwann cells", "why": "Schwann cells myelinate peripheral axons."}, {"text": "Open spaces between arachnoid trabeculae", "why": "These are part of CSF space, not the capillary BBB."}, {"text": "Tight junctions between CNS capillary endothelial cells", "why": "Endothelium forms the BBB seal with supporting neurovascular components."}], "answer": 4}, {"id": "Q125", "ref": "board-barriers", "deck": "board", "topic": "Board integration", "stem": "A tracer readily leaves fenestrated choroid plexus capillaries but is prevented from freely entering ventricular CSF. What provides the relevant barrier?", "options": [{"text": "Open gaps between ordinary ependymal cells", "why": "These do not form the specialized tight choroid barrier."}, {"text": "Myelin around peripheral axons", "why": "This does not separate choroid blood from CSF."}, {"text": "Tight junctions between choroid epithelial cells", "why": "These form the blood-CSF barrier downstream of the fenestrated capillaries."}, {"text": "Dorsal root sensory synapses", "why": "DRG generally lack relay synapses and are not this barrier."}, {"text": "Dural attachments at sutures", "why": "These limit epidural collections, not choroid transfer."}], "answer": 2}, {"id": "Q126", "ref": "board-lp", "deck": "board", "topic": "Board integration", "stem": "An adult needs diagnostic CSF sampling. Which interspace is commonly chosen to enter below the usual end of the spinal cord?", "options": [{"text": "S4-S5", "why": "The dural sac usually ends near S2, so this is below the normal lumbar cistern."}, {"text": "T12-L1 as the safest universal site", "why": "This is too close to typical conus level for the usual preferred approach."}, {"text": "C2-C3 by routine blind midline technique", "why": "This is near spinal cord and is not routine lumbar sampling."}, {"text": "L3-L4", "why": "This accesses the lumbar cistern below the usual L1-L2 conus."}, {"text": "T6-T7", "why": "The spinal cord is present at this level."}], "answer": 3}, {"id": "Q127", "ref": "board-lp", "deck": "board", "topic": "Board integration", "stem": "During a midline LP, the needle passes through ligamentum flavum. Which compartment is encountered next before the dura is pierced?", "options": [{"text": "Subarachnoid space", "why": "Dura and arachnoid must first be traversed."}, {"text": "Celiac ganglion", "why": "This is an abdominal autonomic structure."}, {"text": "Epidural space", "why": "This lies between ligamentum flavum/vertebral canal and dura."}, {"text": "Central canal", "why": "This lies inside the spinal cord and is not the target."}, {"text": "Cerebral aqueduct", "why": "This is in the midbrain."}], "answer": 2}, {"id": "Q128", "ref": "board-lp", "deck": "board", "topic": "Board integration", "stem": "A patient develops headache after an LP that worsens when upright and improves supine. What is the most likely mechanism?", "options": [{"text": "New CSF overproduction by all ependymal cells", "why": "This does not explain the classic postural low-pressure syndrome."}, {"text": "Acute loss of sympathetic gray rami", "why": "This does not create a lumbar dural leak."}, {"text": "Rupture of the middle meningeal artery at pterion", "why": "A lumbar needle does not injure the pterion."}, {"text": "Persistent CSF leakage causing low-pressure headache", "why": "The postural pattern is characteristic of post-dural-puncture headache."}, {"text": "Dandy-Walker malformation acquired from the needle", "why": "This is a congenital malformation."}], "answer": 3}, {"id": "Q129", "ref": "board-csf-patterns", "deck": "board", "topic": "Board integration", "stem": "A febrile patient with neck stiffness has CSF showing neutrophilic pleocytosis, very high protein, and low glucose. Which process is most strongly suggested?", "options": [{"text": "Pure ex vacuo ventriculomegaly", "why": "Atrophy does not cause this CSF inflammatory profile."}, {"text": "NPH", "why": "This does not characteristically cause this inflammatory CSF pattern."}, {"text": "Acute bacterial meningitis", "why": "This is the typical bacterial pattern, interpreted with clinical context and microbiology."}, {"text": "Typical uncomplicated viral meningitis", "why": "Glucose is usually normal and lymphocytes usually predominate."}, {"text": "IIH", "why": "CSF composition should be normal."}], "answer": 2}, {"id": "Q130", "ref": "board-csf-patterns", "deck": "board", "topic": "Board integration", "stem": "A patient with ascending areflexic weakness has elevated CSF protein but few leukocytes. What is this pattern called?", "options": [{"text": "Hydrocephalus ex vacuo", "why": "This is an imaging consequence of tissue loss."}, {"text": "Neutrophilic pleocytosis", "why": "This requires an increased neutrophil count."}, {"text": "Papilledema", "why": "This is an optic disc finding."}, {"text": "Xanthochromia", "why": "This describes yellow coloration, often from blood breakdown."}, {"text": "Albuminocytologic dissociation", "why": "This is characteristic of Guillain-Barré syndrome, though it may be absent early."}], "answer": 4}, {"id": "Q131", "ref": "board-csf-patterns", "deck": "board", "topic": "Board integration", "stem": "A patient with a self-limited febrile headache has CSF lymphocytes, normal glucose, and mildly increased protein. Which diagnosis best fits this typical pattern?", "options": [{"text": "Epidural hematoma", "why": "This is an extra-dural collection, not a typical cause of lymphocytic meningitis."}, {"text": "IIH", "why": "This should have normal CSF composition without pleocytosis."}, {"text": "Ex vacuo ventriculomegaly", "why": "This does not cause inflammatory CSF."}, {"text": "Typical pyogenic bacterial meningitis", "why": "This more often has neutrophils, low glucose, and markedly high protein."}, {"text": "Viral meningitis", "why": "This is a common viral CSF profile."}], "answer": 4}, {"id": "Q132", "ref": "board-pressure", "deck": "board", "topic": "Board integration", "stem": "A patient with Chiari I and a cervical syrinx loses pain and temperature over both shoulders while vibration is preserved. Which fibers are most directly affected?", "options": [{"text": "Dorsal columns exclusively", "why": "These carry vibration/proprioception, which are preserved."}, {"text": "Optic radiation fibers", "why": "These carry vision."}, {"text": "Crossing spinothalamic fibers near the central canal", "why": "A syrinx can interrupt segmental crossing pain-temperature fibers."}, {"text": "Pelvic parasympathetic preganglionic fibers only", "why": "These do not explain a shoulder sensory pattern."}, {"text": "Corticospinal fibers above the pyramids only", "why": "These are motor and do not explain selective pain-temperature loss."}], "answer": 2}, {"id": "Q133", "ref": "board-pressure", "deck": "board", "topic": "Board integration", "stem": "A patient has papilledema, impaired consciousness, and a focal neurologic deficit. LP is being considered for possible infection. What is the most appropriate principle?", "options": [{"text": "Perform immediate LP regardless of examination", "why": "These findings require assessment of herniation risk."}, {"text": "Use a cervical puncture to eliminate herniation risk", "why": "A different puncture site does not remove the underlying pressure problem."}, {"text": "Evaluate for intracranial mass and dangerous pressure gradients before LP", "why": "A mass-related gradient can precipitate herniation when lumbar CSF is removed."}, {"text": "Assume normal ventricles exclude all high ICP", "why": "IIH and other processes can raise pressure without ventricular enlargement."}, {"text": "Withhold all antibiotics until every imaging study is finished", "why": "Suspected bacterial meningitis requires prompt treatment if testing is delayed."}], "answer": 2}, {"id": "Q134", "ref": "1.1-23", "deck": "1.1", "topic": "Glia", "stem": "A brain tumor is composed of malignant astrocytic cells. Which protein is a commonly used marker of astrocytic differentiation?", "options": [{"text": "Myoglobin", "why": "This is a muscle oxygen-binding protein."}, {"text": "GFAP", "why": "Glial fibrillary acidic protein is characteristic of astrocytic differentiation."}, {"text": "Keratin as a specific astrocytic marker", "why": "Keratin is not the characteristic marker asked for."}, {"text": "Thyroglobulin", "why": "This is a thyroid follicular protein."}, {"text": "Insulin", "why": "This is a pancreatic endocrine hormone."}], "answer": 1}, {"id": "Q135", "ref": "1.1-23", "deck": "1.1", "topic": "Glia", "stem": "A patient has a tumor arising from Schwann cells on the vestibular component of CN VIII. Which tumor is most likely?", "options": [{"text": "Glioblastoma", "why": "This is a malignant diffuse astrocytic tumor."}, {"text": "Choroid plexus papilloma", "why": "This arises from ventricular choroid epithelium."}, {"text": "Ependymoma", "why": "This arises from ependymal lineage."}, {"text": "Vestibular schwannoma", "why": "This is a Schwann-cell tumor of the vestibular nerve."}, {"text": "Meningioma", "why": "This arises from arachnoid-associated meningothelial cells."}], "answer": 3}, {"id": "Q136", "ref": "1.2-23", "deck": "1.2", "topic": "Ventricular anatomy", "stem": "A child has vomiting and ataxia from a fourth ventricular tumor that obstructs CSF flow. Histology shows perivascular pseudorosettes. Which tumor is classically associated with this pattern?", "options": [{"text": "Ependymoma", "why": "This ependymal tumor can arise near the fourth ventricle and obstruct CSF flow."}, {"text": "Pituitary adenoma", "why": "This arises in the sella rather than the fourth ventricle."}, {"text": "Adrenal pheochromocytoma", "why": "This is an extracranial chromaffin tumor."}, {"text": "Meningioma", "why": "This is usually dural-based and can show whorls/psammoma bodies."}, {"text": "Vestibular schwannoma", "why": "This is a peripheral nerve-sheath tumor rather than the classic ventricular pseudorosette tumor."}], "answer": 0}, {"id": "Q137", "ref": "1.2-5", "deck": "1.2", "topic": "Skull", "stem": "Which four bones meet at the pterion?", "options": [{"text": "Temporal, lacrimal, inferior concha, vomer", "why": "These do not form the lateral pterion junction."}, {"text": "Occipital, vomer, palatine, ethmoid", "why": "These are not the pterion bones."}, {"text": "Frontal, nasal, maxilla, mandible", "why": "These do not meet at a common pterion junction."}, {"text": "Both parietals and occipital only", "why": "This describes the posterior sagittal/lambdoid region more closely."}, {"text": "Frontal, parietal, sphenoid, temporal", "why": "Their lateral junction overlies the anterior middle meningeal branch."}], "answer": 4}, {"id": "Q138", "ref": "1.2-5", "deck": "1.2", "topic": "Skull", "stem": "At the asterion, which regions meet?", "options": [{"text": "Frontal, parietal, sphenoid, squamous temporal", "why": "This is pterion."}, {"text": "Parietal, occipital, and mastoid temporal", "why": "This is the posterolateral three-bone junction."}, {"text": "Paired parietals and occipital at midline", "why": "This is lambda."}, {"text": "Frontal and paired parietals anteriorly", "why": "This is the bregma region."}, {"text": "Nasal and frontal at the bridge", "why": "This is nasion."}], "answer": 1}, {"id": "Q139", "ref": "1.2-7", "deck": "1.2", "topic": "Skull", "stem": "The zygomatic arch is formed by which processes?", "options": [{"text": "Temporal process of zygomatic and zygomatic process of temporal", "why": "These processes meet to form the lateral cheek arch."}, {"text": "Coronoid and condylar processes of mandible", "why": "These form the mandibular ramus superiorly, not the arch."}, {"text": "Mastoid and styloid processes", "why": "These are separate temporal projections below/behind the ear region."}, {"text": "Frontal and occipital processes", "why": "These do not form the zygomatic arch."}, {"text": "Spinous processes of cervical vertebrae", "why": "These are posterior spinal landmarks."}], "answer": 0}, {"id": "Q140", "ref": "1.2-15", "deck": "1.2", "topic": "Dural partitions", "stem": "Which fold partially separates the two cerebellar hemispheres?", "options": [{"text": "Septum pellucidum", "why": "This is a thin cerebral partition between parts of the lateral ventricles, not a cerebellar dural fold."}, {"text": "Diaphragma sellae", "why": "This roofs the pituitary fossa."}, {"text": "Ligamentum flavum", "why": "This is a spinal ligament."}, {"text": "Falx cerebelli", "why": "This small posterior fossa dural fold lies between cerebellar hemispheres."}, {"text": "Falx cerebri", "why": "This separates cerebral hemispheres."}], "answer": 3}, {"id": "Q141", "ref": "1.2-21", "deck": "1.2", "topic": "Herniation", "stem": "Diffuse cerebral edema causes downward displacement of diencephalic and midbrain structures through the tentorial opening with progressive loss of consciousness. Which herniation pattern is described?", "options": [{"text": "Central transtentorial", "why": "Central downward displacement threatens brainstem function."}, {"text": "Isolated tonsillar", "why": "This specifically displaces cerebellar tonsils through foramen magnum."}, {"text": "Isolated subfalcine", "why": "This is cingulate displacement beneath falx."}, {"text": "Pure ex vacuo enlargement", "why": "This is tissue-loss-associated ventricular expansion rather than acute displacement."}, {"text": "External brain herniation through an open skull defect", "why": "No skull defect is described."}], "answer": 0}, {"id": "Q142", "ref": "board-skull", "deck": "board", "topic": "Board integration", "stem": "Which pairing of cranial nerve and skull opening is correct?", "options": [{"text": "V2 — foramen rotundum", "why": "The maxillary division traverses rotundum."}, {"text": "V3 — optic canal", "why": "V3 exits through foramen ovale."}, {"text": "CN VII — foramen spinosum", "why": "VII enters the temporal bone at internal acoustic meatus and exits through stylomastoid foramen."}, {"text": "CN II — jugular foramen", "why": "II passes through optic canal."}, {"text": "CN XII — internal acoustic meatus", "why": "XII passes through hypoglossal canal."}], "answer": 0}, {"id": "Q143", "ref": "board-skull", "deck": "board", "topic": "Board integration", "stem": "Which nerves normally pass through the jugular foramen?", "options": [{"text": "CN IX, X, and XI", "why": "These accompany venous outflow through the jugular foramen."}, {"text": "CN V1 and V2 only", "why": "These use superior orbital fissure and rotundum."}, {"text": "CN XII only", "why": "This uses hypoglossal canal."}, {"text": "CN II, III, and IV", "why": "These use orbital passages rather than jugular foramen."}, {"text": "CN VII and VIII only", "why": "These use internal acoustic meatus."}], "answer": 0}, {"id": "Q144", "ref": "board-barriers", "deck": "board", "topic": "Board integration", "stem": "A circulating emetic substance is detected at a medullary structure with specialized permeable capillaries. Which structure is most likely involved?", "options": [{"text": "Celiac ganglion", "why": "This is an abdominal autonomic ganglion."}, {"text": "Typical cortical capillary with an intact BBB", "why": "Its tight barrier restricts free blood-borne access."}, {"text": "Lens of the eye", "why": "This is not a medullary chemosensory structure."}, {"text": "Area postrema", "why": "This circumventricular structure can sense circulating emetic signals."}, {"text": "Dorsal root ganglion inside the medulla", "why": "DRG are peripheral and not medullary structures."}], "answer": 3}, {"id": "Q145", "ref": "board-lp", "deck": "board", "topic": "Board integration", "stem": "A spinal anesthetic is intentionally administered into CSF. Which compartment receives the drug?", "options": [{"text": "Subcutaneous tissue only", "why": "This would not be intrathecal administration."}, {"text": "Subarachnoid space", "why": "Intrathecal/spinal anesthesia enters CSF between arachnoid and pia."}, {"text": "Epidural space", "why": "Epidural anesthesia is outside dura and does not intentionally enter CSF."}, {"text": "Dorsal root ganglion cell body", "why": "This is not a fluid compartment for spinal anesthesia."}, {"text": "Central canal of spinal cord", "why": "This is not the routine needle target."}], "answer": 1}]};
